import { Colors } from '@/constants/Colors';
import { useColorScheme } from '@/hooks/useColorScheme';
import { useRequireAdmin } from '@/hooks/useRequireAdmin';
import { Stack } from 'expo-router';
import { useCallback, useEffect, useState } from 'react';
import { ActivityIndicator, FlatList, StyleSheet, Text, View } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
// @ts-ignore
import { Message as MsgApi, User } from '@/api/entities';

export default function AdminMessagesScreen() {
  const colorScheme = useColorScheme() ?? 'light';
    const { isAdmin, loading: _authLoading } = useRequireAdmin();
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [items, setItems] = useState<any[]>([]);

  const load = useCallback(async () => {
      if (!isAdmin) return;
    setLoading(true); setError(null);
    try {
      await User.me();
      const list = await MsgApi.listAll(200);
      setItems(Array.isArray(list) ? list : []);
    } catch (e: any) {
      setError(e?.status === 403 ? 'Access denied (admin only).' : (e?.message || 'Failed to load messages'));
    } finally { setLoading(false); }
  }, [isAdmin]);

  useEffect(() => { load(); }, [load]);

  return (
    <SafeAreaView style={[styles.container, { backgroundColor: Colors[colorScheme].background }]} edges={['top', 'bottom']}>
      <Stack.Screen options={{ title: 'Admin · All Messages' }} />
      {loading ? <View style={{ padding: 24, alignItems: 'center' }}><ActivityIndicator /></View> : null}
      {error ? <Text style={[styles.error, { color: Colors[colorScheme].mutedText }]}>{error}</Text> : null}
      {!loading && !error && (
        <FlatList
          data={items}
          keyExtractor={(m) => String(m.id)}
          renderItem={({ item }) => (
            <View style={[styles.row, { backgroundColor: Colors[colorScheme].card, borderColor: Colors[colorScheme].border }]}>
              <Text style={[styles.msg, { color: Colors[colorScheme].text }]} numberOfLines={2}>{item.content || ''}</Text>
              <Text style={[styles.meta, { color: Colors[colorScheme].mutedText }]}>{(item.sender_email || 'unknown') + ' → ' + (item.recipient_email || 'unknown')}</Text>
              <Text style={[styles.meta, { color: Colors[colorScheme].mutedText }]}>{new Date(item.created_date || item.created_at || Date.now()).toLocaleString()}</Text>
            </View>
          )}
          ItemSeparatorComponent={() => <View style={{ height: 8 }} />}
          contentContainerStyle={{ padding: 16, paddingBottom: 24 }}
        />
      )}
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  container: { flex: 1 },
  row: { padding: 12, borderRadius: 12, borderWidth: StyleSheet.hairlineWidth },
  msg: { fontWeight: '600' },
  meta: {},
  error: { padding: 12 },
});

import { useColorScheme } from '@/hooks/useColorScheme';
import { useRequireAdmin } from '@/hooks/useRequireAdmin';
import { Ionicons } from '@expo/vector-icons';
import { Stack, useRouter } from 'expo-router';
import { useCallback, useEffect, useState } from 'react';
import {
    ActivityIndicator,
    Alert,
    Pressable,
    RefreshControl,
    ScrollView,
    StyleSheet,
    Text,
    View
} from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import { getApiBaseUrl } from '../api/http';

interface AbuseReport {
  id: string;
  reporter_name: string;
  reporter_email: string;
  subject: string;
  message: string;
  status: 'pending' | 'reviewed' | 'resolved' | 'dismissed';
  created_at: string;
  reviewed_at?: string;
  resolution_note?: string;
  reporter: {
    id: string;
    display_name: string;
    email: string;
    avatar_url?: string;
    banned: boolean;
  };
}

interface ReportStats {
  pending: number;
  reviewed: number;
  resolved: number;
  dismissed: number;
  total: number;
}

export default function AdminReportsScreen() {
  const colorScheme = useColorScheme() ?? 'light';
    const { isAdmin, loading: _authLoading } = useRequireAdmin();
  const router = useRouter();
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [reports, setReports] = useState<AbuseReport[]>([]);
  const [stats, setStats] = useState<ReportStats | null>(null);
  const [selectedReports, setSelectedReports] = useState<Set<string>>(new Set());
  const [filterStatus, setFilterStatus] = useState<string>('all');

  const loadReports = useCallback(async (showRefreshing = false) => {
    if (showRefreshing) setRefreshing(true);
    else setLoading(true);
    setError(null);

    try {
      const token = await (await import('@/api/auth')).loadToken();
      const apiUrl = getApiBaseUrl();

      const [reportsRes, statsRes] = await Promise.all([
        fetch(`${apiUrl}/admin/reports?status=${filterStatus}`, {
          headers: {
            'Authorization': `Bearer ${token}`,
            'Content-Type': 'application/json',
          },
        }),
        fetch(`${apiUrl}/admin/reports/stats`, {
          headers: {
            'Authorization': `Bearer ${token}`,
            'Content-Type': 'application/json',
          },
        }),
      ]);

      if (!reportsRes.ok || !statsRes.ok) {
        throw new Error('Failed to load reports');
      }

      const reportsData = await reportsRes.json();
      const statsData = await statsRes.json();

      setReports(reportsData.reports || []);
      setStats(statsData);
    } catch (e: any) {
      setError(e?.message || 'Failed to load reports');
    } finally {
      setLoading(false);
      setRefreshing(false);
    }
  }, [filterStatus]);

  useEffect(() => {
    loadReports();
  }, [loadReports]);

  const onRefresh = () => {
    loadReports(true);
  };

  const toggleSelectReport = (id: string) => {
    const newSelected = new Set(selectedReports);
    if (newSelected.has(id)) {
      newSelected.delete(id);
    } else {
      newSelected.add(id);
    }
    setSelectedReports(newSelected);
  };

  const selectAll = () => {
    setSelectedReports(new Set(reports.map(r => r.id)));
  };

  const deselectAll = () => {
    setSelectedReports(new Set());
  };

  const updateReportStatus = async (reportId: string, status: string, resolutionNote?: string) => {
    try {
      const token = await (await import('@/api/auth')).loadToken();
      const apiUrl = getApiBaseUrl();

      const response = await fetch(`${apiUrl}/admin/reports/${reportId}`, {
        method: 'PATCH',
        headers: {
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ status, resolution_note: resolutionNote }),
      });

      if (!response.ok) {
        throw new Error('Failed to update report');
      }

      loadReports(true);
      Alert.alert('Success', 'Report updated successfully');
    } catch (e: any) {
      Alert.alert('Error', e?.message || 'Failed to update report');
    }
  };

  const bulkUpdateStatus = async (status: string) => {
    if (selectedReports.size === 0) {
      Alert.alert('No Reports Selected', 'Please select at least one report');
      return;
    }

    try {
      const token = await (await import('@/api/auth')).loadToken();
      const apiUrl = getApiBaseUrl();

      const response = await fetch(`${apiUrl}/admin/reports/bulk-update`, {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ 
          report_ids: Array.from(selectedReports), 
          status 
        }),
      });

      if (!response.ok) {
        throw new Error('Failed to update reports');
      }

      const data = await response.json();
      setSelectedReports(new Set());
      loadReports(true);
      Alert.alert('Success', `Updated ${data.updated} reports`);
    } catch (e: any) {
      Alert.alert('Error', e?.message || 'Failed to update reports');
    }
  };

  const bulkDelete = async () => {
    if (selectedReports.size === 0) {
      Alert.alert('No Reports Selected', 'Please select at least one report');
      return;
    }

    Alert.alert(
      'Confirm Delete',
      `Delete ${selectedReports.size} selected report(s)?`,
      [
        { text: 'Cancel', style: 'cancel' },
        { 
          text: 'Delete', 
          style: 'destructive',
          onPress: async () => {
            try {
              const token = await (await import('@/api/auth')).loadToken();
              const apiUrl = getApiBaseUrl();

              const response = await fetch(`${apiUrl}/admin/reports/bulk-delete`, {
                method: 'POST',
                headers: {
                  'Authorization': `Bearer ${token}`,
                  'Content-Type': 'application/json',
                },
                body: JSON.stringify({ report_ids: Array.from(selectedReports) }),
              });

              if (!response.ok) {
                throw new Error('Failed to delete reports');
              }

              const data = await response.json();
              setSelectedReports(new Set());
              loadReports(true);
              Alert.alert('Success', `Deleted ${data.deleted} reports`);
            } catch (e: any) {
              Alert.alert('Error', e?.message || 'Failed to delete reports');
            }
          }
        },
      ]
    );
  };

  const StatusBadge = ({ status }: { status: string }) => {
    const colors = {
      pending: '#F59E0B',
      reviewed: '#3B82F6',
      resolved: '#10B981',
      dismissed: '#6B7280',
    };

    return (
      <View style={[styles.badge, { backgroundColor: colors[status as keyof typeof colors] + '20' }]}>
        <Text style={[styles.badgeText, { color: colors[status as keyof typeof colors] }]}>
          {status.charAt(0).toUpperCase() + status.slice(1)}
        </Text>
      </View>
    );
  };

  const ReportCard = ({ report }: { report: AbuseReport }) => {
    const isSelected = selectedReports.has(report.id);

    return (
      <Pressable 
        style={[styles.reportCard, { 
          backgroundColor: colorScheme === 'dark' ? '#1F2937' : 'white',
          borderColor: isSelected 
            ? '#3B82F6' 
            : (colorScheme === 'dark' ? '#374151' : '#E5E7EB'),
          borderWidth: isSelected ? 2 : 1,
        }]}
        onPress={() => toggleSelectReport(report.id)}
      >
        <View style={styles.reportHeader}>
          <View style={styles.reportHeaderLeft}>
            <Ionicons 
              name={isSelected ? 'checkbox' : 'square-outline'} 
              size={24} 
              color={isSelected ? '#3B82F6' : (colorScheme === 'dark' ? '#9CA3AF' : '#6B7280')} 
            />
            <View style={{ marginLeft: 12 }}>
              <Text style={[styles.reporterName, { color: colorScheme === 'dark' ? '#ECEDEE' : '#111827' }]}>
                {report.reporter_name}
              </Text>
              <Text style={[styles.reporterEmail, { color: colorScheme === 'dark' ? '#9CA3AF' : '#6B7280' }]}>
                {report.reporter_email}
              </Text>
            </View>
          </View>
          <StatusBadge status={report.status} />
        </View>

        <Text style={[styles.reportSubject, { color: colorScheme === 'dark' ? '#ECEDEE' : '#111827' }]}>
          {report.subject}
        </Text>

        <Text 
          style={[styles.reportMessage, { color: colorScheme === 'dark' ? '#9CA3AF' : '#6B7280' }]}
          numberOfLines={3}
        >
          {report.message}
        </Text>

        <View style={styles.reportFooter}>
          <Text style={[styles.reportDate, { color: colorScheme === 'dark' ? '#6B7280' : '#9CA3AF' }]}>
            {new Date(report.created_at).toLocaleDateString()} {new Date(report.created_at).toLocaleTimeString()}
          </Text>
          <View style={styles.reportActions}>
            <Pressable 
              style={[styles.actionBtn, { backgroundColor: '#10B981' + '20' }]}
              onPress={() => updateReportStatus(report.id, 'resolved')}
            >
              <Text style={[styles.actionBtnText, { color: '#10B981' }]}>Resolve</Text>
            </Pressable>
            <Pressable 
              style={[styles.actionBtn, { backgroundColor: '#6B7280' + '20' }]}
              onPress={() => updateReportStatus(report.id, 'dismissed')}
            >
              <Text style={[styles.actionBtnText, { color: '#6B7280' }]}>Dismiss</Text>
            </Pressable>
          </View>
        </View>
      </Pressable>
    );
  };

  return (
    <SafeAreaView 
      edges={['top']}
      style={{ flex: 1, backgroundColor: colorScheme === 'dark' ? '#0F172A' : '#F9FAFB' }}
    >
      <Stack.Screen options={{ headerShown: false }} />

      <ScrollView
        style={styles.container}
        contentContainerStyle={styles.contentContainer}
        refreshControl={
          <RefreshControl refreshing={refreshing} onRefresh={onRefresh} />
        }
      >
        {/* Header */}
        <View style={[styles.header, { backgroundColor: colorScheme === 'dark' ? '#1E293B' : 'white' }]}>
          <Pressable onPress={() => void router.back()} style={styles.backButton}>
            <Ionicons 
              name="arrow-back" 
              size={24} 
              color={colorScheme === 'dark' ? '#ECEDEE' : '#111827'} 
            />
          </Pressable>
          <Text style={[styles.headerTitle, { color: colorScheme === 'dark' ? '#ECEDEE' : '#111827' }]}>
            Abuse Reports
          </Text>
          <View style={styles.headerRight}>
            <Ionicons 
              name="alert-circle-outline" 
              size={24} 
              color={colorScheme === 'dark' ? '#9CA3AF' : '#6B7280'} 
            />
          </View>
        </View>

        {loading && !refreshing ? (
          <View style={styles.centerContainer}>
            <ActivityIndicator size="large" color="#3B82F6" />
          </View>
        ) : error ? (
          <View style={styles.centerContainer}>
            <Ionicons name="alert-circle" size={48} color="#EF4444" />
            <Text style={[styles.errorText, { color: colorScheme === 'dark' ? '#F87171' : '#EF4444' }]}>
              {error}
            </Text>
            <Pressable style={styles.retryButton} onPress={() => loadReports()}>
              <Text style={styles.retryButtonText}>Try Again</Text>
            </Pressable>
          </View>
        ) : (
          <>
            {/* Stats */}
            {stats && (
              <View style={styles.statsContainer}>
                <View style={[styles.statBox, { backgroundColor: colorScheme === 'dark' ? '#1F2937' : 'white' }]}>
                  <Text style={[styles.statNumber, { color: '#F59E0B' }]}>{stats.pending}</Text>
                  <Text style={[styles.statLabel, { color: colorScheme === 'dark' ? '#9CA3AF' : '#6B7280' }]}>
                    Pending
                  </Text>
                </View>
                <View style={[styles.statBox, { backgroundColor: colorScheme === 'dark' ? '#1F2937' : 'white' }]}>
                  <Text style={[styles.statNumber, { color: '#10B981' }]}>{stats.resolved}</Text>
                  <Text style={[styles.statLabel, { color: colorScheme === 'dark' ? '#9CA3AF' : '#6B7280' }]}>
                    Resolved
                  </Text>
                </View>
                <View style={[styles.statBox, { backgroundColor: colorScheme === 'dark' ? '#1F2937' : 'white' }]}>
                  <Text style={[styles.statNumber, { color: '#6B7280' }]}>{stats.dismissed}</Text>
                  <Text style={[styles.statLabel, { color: colorScheme === 'dark' ? '#9CA3AF' : '#6B7280' }]}>
                    Dismissed
                  </Text>
                </View>
                <View style={[styles.statBox, { backgroundColor: colorScheme === 'dark' ? '#1F2937' : 'white' }]}>
                  <Text style={[styles.statNumber, { color: '#3B82F6' }]}>{stats.total}</Text>
                  <Text style={[styles.statLabel, { color: colorScheme === 'dark' ? '#9CA3AF' : '#6B7280' }]}>
                    Total
                  </Text>
                </View>
              </View>
            )}

            {/* Filter Tabs */}
            <ScrollView horizontal showsHorizontalScrollIndicator={false} style={styles.filterContainer}>
              {['all', 'pending', 'reviewed', 'resolved', 'dismissed'].map(status => (
                <Pressable
                  key={status}
                  style={[
                    styles.filterTab,
                    {
                      backgroundColor: filterStatus === status
                        ? '#3B82F6'
                        : (colorScheme === 'dark' ? '#1F2937' : 'white'),
                    },
                  ]}
                  onPress={() => setFilterStatus(status)}
                >
                  <Text
                    style={[
                      styles.filterTabText,
                      {
                        color: filterStatus === status
                          ? 'white'
                          : (colorScheme === 'dark' ? '#9CA3AF' : '#6B7280'),
                      },
                    ]}
                  >
                    {status.charAt(0).toUpperCase() + status.slice(1)}
                  </Text>
                </Pressable>
              ))}
            </ScrollView>

            {/* Bulk Actions */}
            {selectedReports.size > 0 && (
              <View style={[styles.bulkActionsBar, { backgroundColor: colorScheme === 'dark' ? '#1F2937' : 'white' }]}>
                <Text style={[styles.bulkActionsText, { color: colorScheme === 'dark' ? '#ECEDEE' : '#111827' }]}>
                  {selectedReports.size} selected
                </Text>
                <View style={styles.bulkActionsButtons}>
                  <Pressable style={styles.bulkActionBtn} onPress={selectAll}>
                    <Text style={styles.bulkActionBtnText}>All</Text>
                  </Pressable>
                  <Pressable style={styles.bulkActionBtn} onPress={deselectAll}>
                    <Text style={styles.bulkActionBtnText}>None</Text>
                  </Pressable>
                  <Pressable 
                    style={[styles.bulkActionBtn, { backgroundColor: '#10B981' }]} 
                    onPress={() => bulkUpdateStatus('resolved')}
                  >
                    <Text style={[styles.bulkActionBtnText, { color: 'white' }]}>Resolve</Text>
                  </Pressable>
                  <Pressable 
                    style={[styles.bulkActionBtn, { backgroundColor: '#6B7280' }]} 
                    onPress={() => bulkUpdateStatus('dismissed')}
                  >
                    <Text style={[styles.bulkActionBtnText, { color: 'white' }]}>Dismiss</Text>
                  </Pressable>
                  <Pressable 
                    style={[styles.bulkActionBtn, { backgroundColor: '#EF4444' }]} 
                    onPress={bulkDelete}
                  >
                    <Text style={[styles.bulkActionBtnText, { color: 'white' }]}>Delete</Text>
                  </Pressable>
                </View>
              </View>
            )}

            {/* Reports List */}
            <View style={styles.reportsSection}>
              {reports.length === 0 ? (
                <View style={styles.emptyState}>
                  <Ionicons 
                    name="document-text-outline" 
                    size={64} 
                    color={colorScheme === 'dark' ? '#6B7280' : '#9CA3AF'} 
                  />
                  <Text style={[styles.emptyStateText, { color: colorScheme === 'dark' ? '#9CA3AF' : '#6B7280' }]}>
                    No reports found
                  </Text>
                </View>
              ) : (
                reports.map(report => <ReportCard key={report.id} report={report} />)
              )}
            </View>
          </>
        )}
      </ScrollView>
    </SafeAreaView>
  );
}

