import { Colors } from '@/constants/Colors';
import { useColorScheme } from '@/hooks/useColorScheme';
import { useRequireAdmin } from '@/hooks/useRequireAdmin';
import { Ionicons } from '@expo/vector-icons';
import { Stack, useRouter } from 'expo-router';
import { useCallback, useEffect, useState } from 'react';
import { ActivityIndicator, Alert, FlatList, Pressable, StyleSheet, Text, View } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
// @ts-ignore
import { Team as TeamApi, User } from '@/api/entities';

export default function AdminTeamsScreen() {
  const colorScheme = useColorScheme() ?? 'light';
    const { isAdmin, loading: _authLoading } = useRequireAdmin();
  const router = useRouter();
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [teams, setTeams] = useState<any[]>([]);
  const [bulkMode, setBulkMode] = useState(false);
  const [selectedTeams, setSelectedTeams] = useState<Set<string>>(new Set());
  const [deleting, setDeleting] = useState(false);

  const load = useCallback(async () => {
      if (!isAdmin) return;
    setLoading(true); setError(null);
    try {
      await User.me();
      const list = await TeamApi.list('', false); // Explicitly pass false for mine parameter to get all teams
      setTeams(Array.isArray(list) ? list : []);
    } catch (e: any) {
      setError(e?.status === 403 ? 'Access denied (admin only).' : (e?.message || 'Failed to load teams'));
    } finally { setLoading(false); }
  }, [isAdmin]);

  useEffect(() => { load(); }, [load]);

  const toggleTeamSelection = (teamId: string) => {
    const newSet = new Set(selectedTeams);
    if (newSet.has(teamId)) {
      newSet.delete(teamId);
    } else {
      newSet.add(teamId);
    }
    setSelectedTeams(newSet);
  };

  const selectAll = () => {
    if (selectedTeams.size === teams.length) {
      setSelectedTeams(new Set());
    } else {
      setSelectedTeams(new Set(teams.map(t => String(t.id))));
    }
  };

  const bulkDelete = async () => {
    if (selectedTeams.size === 0) return;

    Alert.alert(
      'Delete Teams',
      `Delete ${selectedTeams.size} team${selectedTeams.size > 1 ? 's' : ''}? This cannot be undone.`,
      [
        { text: 'Cancel', style: 'cancel' },
        {
          text: 'Delete',
          style: 'destructive',
          onPress: async () => {
            setDeleting(true);
            try {
              // Delete each selected team
              for (const teamId of Array.from(selectedTeams)) {
                try {
                  await TeamApi.delete(teamId);
                } catch (e) {
                  console.error('Failed to delete team:', teamId, e);
                }
              }
              Alert.alert('Success', `Deleted ${selectedTeams.size} team${selectedTeams.size > 1 ? 's' : ''}`);
              setSelectedTeams(new Set());
              setBulkMode(false);
              await load();
            } catch (e: any) {
              Alert.alert('Error', e?.message || 'Failed to delete teams');
            } finally {
              setDeleting(false);
            }
          }
        }
      ]
    );
  };

  const theme = Colors[colorScheme];

  return (
    <SafeAreaView style={[styles.container, { backgroundColor: theme.background }]} edges={['top', 'bottom']}>
      <Stack.Screen 
        options={{ 
          title: 'Admin · All Teams',
          headerRight: () => (
            <View style={{ flexDirection: 'row', gap: 12, marginRight: 8 }}>
              {bulkMode && (
                <>
                  <Pressable onPress={selectAll} style={{ padding: 8 }}>
                    <Text style={{ color: theme.tint, fontWeight: '600' }}>
                      {selectedTeams.size === teams.length ? 'Deselect All' : 'Select All'}
                    </Text>
                  </Pressable>
                  <Pressable 
                    onPress={bulkDelete} 
                    disabled={selectedTeams.size === 0 || deleting}
                    style={{ padding: 8 }}
                  >
                    <Text style={{ 
                      color: selectedTeams.size > 0 ? '#dc2626' : '#9ca3af', 
                      fontWeight: '600' 
                    }}>
                      Delete ({selectedTeams.size})
                    </Text>
                  </Pressable>
                </>
              )}
              <Pressable onPress={() => setBulkMode(!bulkMode)} style={{ padding: 8 }}>
                <Ionicons 
                  name={bulkMode ? 'close' : 'checkmark-circle-outline'} 
                  size={24} 
                  color={bulkMode ? '#dc2626' : theme.tint} 
                />
              </Pressable>
              <Pressable onPress={() => void router.push('/create-team')} style={{ padding: 8 }}>
                <Ionicons name="add-circle" size={24} color={theme.tint} />
              </Pressable>
            </View>
          )
        }} 
      />

      {loading ? (
        <View style={{ padding: 24, alignItems: 'center' }}>
          <ActivityIndicator color={theme.tint} />
        </View>
      ) : null}

      {error ? (
        <Text style={[styles.error, { color: '#dc2626' }]}>{error}</Text>
      ) : null}

      {!loading && !error && (
        <FlatList
          data={teams}
          keyExtractor={(t) => String(t.id)}
          renderItem={({ item }) => (
            <Pressable 
              style={[
                styles.row, 
                { 
                  backgroundColor: theme.card, 
                  borderColor: theme.border 
                },
                bulkMode && selectedTeams.has(String(item.id)) && {
                  borderColor: theme.tint,
                  borderWidth: 2
                }
              ]}
              onPress={() => {
                if (bulkMode) {
                  toggleTeamSelection(String(item.id));
                } else {
                  router.push({ pathname: '/team-profile', params: { id: item.id } });
                }
              }}
            >
              <View style={{ flexDirection: 'row', alignItems: 'center', gap: 12 }}>
                {bulkMode && (
                  <View style={{
                    width: 24,
                    height: 24,
                    borderRadius: 12,
                    borderWidth: 2,
                    borderColor: selectedTeams.has(String(item.id)) ? theme.tint : '#d1d5db',
                    backgroundColor: selectedTeams.has(String(item.id)) ? theme.tint : 'transparent',
                    alignItems: 'center',
                    justifyContent: 'center'
                  }}>
                    {selectedTeams.has(String(item.id)) && (
                      <Ionicons name="checkmark" size={16} color="#ffffff" />
                    )}
                  </View>
                )}
                <View style={{ flex: 1 }}>
                  <Text style={[styles.title, { color: theme.text }]}>{item.name}</Text>
                  {item.description ? (
                    <Text style={[styles.meta, { color: theme.mutedText }]} numberOfLines={2}>
                      {item.description}
                    </Text>
                  ) : null}
                  <View style={{ flexDirection: 'row', gap: 12, marginTop: 4 }}>
                    <Text style={[styles.meta, { color: theme.mutedText }]}>
                      <Ionicons name="people" size={12} /> {item.members || 0} members
                    </Text>
                    {item.sport && (
                      <Text style={[styles.meta, { color: theme.mutedText }]}>
                        <Ionicons name="american-football" size={12} /> {item.sport}
                      </Text>
                    )}
                  </View>
                </View>
                {!bulkMode && (
                  <Pressable 
                    onPress={() => void router.push({ pathname: '/edit-team', params: { id: item.id } })}
                    style={{ padding: 8 }}
                  >
                    <Ionicons name="pencil" size={20} color={theme.tint} />
                  </Pressable>
                )}
              </View>
            </Pressable>
          )}
          ItemSeparatorComponent={() => <View style={{ height: 8 }} />}
          contentContainerStyle={{ padding: 16, paddingBottom: 24 }}
          ListEmptyComponent={
            <View style={{ padding: 32, alignItems: 'center' }}>
              <Ionicons name="people-outline" size={64} color={theme.mutedText} />
              <Text style={{ color: theme.mutedText, fontSize: 16, marginTop: 16 }}>
                No teams found
              </Text>
            </View>
          }
        />
      )}
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  container: { flex: 1 },
  row: { 
    padding: 16, 
    borderRadius: 12, 
    borderWidth: StyleSheet.hairlineWidth,
    shadowColor: '#000',
    shadowOffset: { width: 0, height: 1 },
    shadowOpacity: 0.05,
    shadowRadius: 2,
    elevation: 1
  },
  title: { 
    fontWeight: '800', 
    fontSize: 16,
    marginBottom: 4
  },
  meta: { 
    fontSize: 13,
    marginTop: 2
  },
  error: { 
    padding: 16,
    textAlign: 'center',
    fontWeight: '600'
  },
});

import { Colors } from '@/constants/Colors';
import { useColorScheme } from '@/hooks/useColorScheme';
import { useRequireAdmin } from '@/hooks/useRequireAdmin';
import { Stack, useLocalSearchParams } from 'expo-router';
import * as WebBrowser from 'expo-web-browser';
import { useCallback, useEffect, useState } from 'react';
import { ActivityIndicator, FlatList, Pressable, StyleSheet, Text, View } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import { getApiBaseUrl } from '../api/http';
// @ts-ignore
import { User } from '@/api/entities';

export default function AdminUserDetailScreen() {
  const colorScheme = useColorScheme() ?? 'light';
    const { isAdmin, loading: _authLoading } = useRequireAdmin();
  const { id } = useLocalSearchParams<{ id?: string }>();
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [detail, setDetail] = useState<any>(null);

  const load = useCallback(async () => {
      if (!isAdmin) return;
    if (!id) return;
    setLoading(true); setError(null);
    try {
      const d = await User.getFull(String(id));
      setDetail(d);
    } catch (e: any) {
      setError(e?.status === 403 ? 'Access denied (admin only).' : (e?.message || 'Failed to load user'));
    } finally { setLoading(false); }
  }, [id]);

  useEffect(() => { load(); }, [load]);

  const onDownload = async () => {
    if (!id) return;
    const url = getApiBaseUrl() + `/users/${encodeURIComponent(String(id))}/export`;
    try { await WebBrowser.openBrowserAsync(url); } catch {}
  };

  const ads = detail?.ads || [];
  const datesByAd = detail?.datesByAd || {};

  return (
    <SafeAreaView style={[styles.container, { backgroundColor: Colors[colorScheme].background }]} edges={['top', 'bottom']}>
      <Stack.Screen options={{ title: 'Admin · User Detail' }} />
      {loading ? <View style={{ padding: 24, alignItems: 'center' }}><ActivityIndicator /></View> : null}
      {error ? <Text style={[styles.error, { color: Colors[colorScheme].mutedText }]}>{error}</Text> : null}
      {!loading && !error && detail ? (
        <>
          <View style={[styles.header, { borderBottomColor: Colors[colorScheme].border }]}>
            <Text style={[styles.title, { color: Colors[colorScheme].text }]}>{detail.user?.display_name || '(no name)'}</Text>
            <Text style={[styles.meta, { color: Colors[colorScheme].mutedText }]}>{detail.user?.email}</Text>
            <View style={{ flexDirection: 'row', gap: 6, marginTop: 6 }}>
              <View style={[styles.badge, { backgroundColor: Colors[colorScheme].card, borderColor: Colors[colorScheme].border }]}>
                <Text style={[styles.badgeText, { color: Colors[colorScheme].text }]}>{detail.user?.email_verified ? 'VERIFIED' : 'UNVERIFIED'}</Text>
              </View>
              {detail.user?.banned ? <View style={[styles.badge, { backgroundColor: '#FEE2E2', borderColor: '#FCA5A5' }]}><Text style={[styles.badgeText, { color: '#991B1B' }]}>BANNED</Text></View> : null}
            </View>
            <Pressable style={[styles.btn, { backgroundColor: Colors[colorScheme].tint }]} onPress={onDownload}><Text style={styles.btnText}>Download Ads CSV</Text></Pressable>
          </View>
          <FlatList
            data={ads}
            keyExtractor={(a) => String(a.id)}
            renderItem={({ item }) => (
              <View style={[styles.card, { backgroundColor: Colors[colorScheme].card, borderColor: Colors[colorScheme].border }]}>
                <Text style={[styles.cardTitle, { color: Colors[colorScheme].text }]}>{item.business_name || '(no business)'}</Text>
                <Text style={[styles.meta, { color: Colors[colorScheme].mutedText }]}>Status: {item.status || 'draft'} · Payment: {item.payment_status || 'unpaid'}</Text>
                <Text style={[styles.meta, { color: Colors[colorScheme].mutedText }]}>Zip {item.target_zip_code || ''}</Text>
                <Text style={[styles.meta, { color: Colors[colorScheme].mutedText }]}>Dates: {(datesByAd[item.id] || []).join(', ') || '—'}</Text>
              </View>
            )}
            ItemSeparatorComponent={() => <View style={{ height: 8 }} />}
            contentContainerStyle={{ padding: 16, paddingBottom: 24 }}
          />
        </>
      ) : null}
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  container: { flex: 1 },
  header: { padding: 16, gap: 6, borderBottomWidth: StyleSheet.hairlineWidth },
  title: { fontWeight: '800', fontSize: 18 },
  meta: {},
  badge: { paddingHorizontal: 8, paddingVertical: 2, borderRadius: 999, borderWidth: StyleSheet.hairlineWidth },
  badgeText: { fontWeight: '800', fontSize: 10 },
  btn: { alignSelf: 'flex-start', borderRadius: 10, paddingHorizontal: 12, paddingVertical: 8, marginTop: 8 },
  btnText: { color: 'white', fontWeight: '800' },
  card: { padding: 12, borderRadius: 12, backgroundColor: '#F9FAFB', borderWidth: StyleSheet.hairlineWidth, borderColor: '#E5E7EB' },
  cardTitle: { fontWeight: '800' },
  error: { color: '#b91c1c', padding: 12 },
});

import { Colors } from '@/constants/Colors';
import { useColorScheme } from '@/hooks/useColorScheme';
import { useRequireAdmin } from '@/hooks/useRequireAdmin';
import { Stack, useRouter } from 'expo-router';
import { useCallback, useEffect, useState } from 'react';
import { ActivityIndicator, FlatList, Pressable, StyleSheet, Text, TextInput, View } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
// @ts-ignore
import { User } from '@/api/entities';

export default function AdminUsersScreen() {
  const colorScheme = useColorScheme() ?? 'light';
  const router = useRouter();
  const { isAdmin, loading: _authLoading } = useRequireAdmin();

  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [items, setItems] = useState<any[]>([]);
  const [q, setQ] = useState('');
  const [showBanned, setShowBanned] = useState(false);

  const load = useCallback(async () => {
    if (!isAdmin) return; // Don't load if not admin

    setLoading(true); setError(null);
    try {
      const list = await User.listAll(q, 200, showBanned);
      setItems(Array.isArray(list) ? list : []);
    } catch (e: any) {
      setError(e?.status === 403 ? 'Access denied (admin only).' : (e?.message || 'Failed to load users'));
    } finally { setLoading(false); }
  }, [q, showBanned, isAdmin]);

  useEffect(() => { load(); }, [load]);

  const toggleBan = async (id: string, banned: boolean) => {
    try {
      if (banned) await User.unban(id); else await User.ban(id);
      await load();
    } catch {}
  };

  return (
    <SafeAreaView style={[styles.container, { backgroundColor: Colors[colorScheme].background }]} edges={['top', 'bottom']}>
      <Stack.Screen options={{ title: 'Admin · Users' }} />
      <View style={styles.bar}>
        <TextInput value={q} onChangeText={setQ} placeholder="Search by name or email" placeholderTextColor={Colors[colorScheme].mutedText} style={[styles.search, { backgroundColor: Colors[colorScheme].card, borderColor: Colors[colorScheme].border, color: Colors[colorScheme].text }]} />
        <Pressable style={[styles.toggle, { borderColor: Colors[colorScheme].border }, showBanned && { backgroundColor: Colors[colorScheme].tint }]} onPress={() => setShowBanned((x) => !x)}>
          <Text style={[styles.toggleText, { color: showBanned ? '#fff' : Colors[colorScheme].text }]}>Banned</Text>
        </Pressable>
      </View>
      {loading ? <View style={{ padding: 24, alignItems: 'center' }}><ActivityIndicator /></View> : null}
      {error ? <Text style={styles.error}>{error}</Text> : null}
      {!loading && !error && (
        <FlatList
          data={items}
          keyExtractor={(u) => String(u.id)}
          renderItem={({ item }) => (
            <View style={styles.row}>
              <Text style={styles.title}>{item.display_name || '(no display)'}</Text>
              <Text style={styles.meta}>{item.email}</Text>
              <View style={{ flexDirection: 'row', gap: 6, marginTop: 6 }}>
                <View style={styles.badge}><Text style={styles.badgeText}>{item.email_verified ? 'VERIFIED' : 'UNVERIFIED'}</Text></View>
                {item.banned ? <View style={[styles.badge, { backgroundColor: '#FEE2E2', borderColor: '#FCA5A5' }]}><Text style={[styles.badgeText, { color: '#991B1B' }]}>BANNED</Text></View> : null}
              </View>
              <View style={{ flexDirection: 'row', gap: 8, marginTop: 8 }}>
                <Pressable style={styles.btn} onPress={() => toggleBan(String(item.id), !!item.banned)}>
                  <Text style={styles.btnText}>{item.banned ? 'Unban' : 'Ban'}</Text>
                </Pressable>
                <Pressable style={[styles.btn, { backgroundColor: '#374151' }]} onPress={() => void router.push(`/admin-user-detail?id=${encodeURIComponent(String(item.id))}`)}>
                  <Text style={styles.btnText}>View</Text>
                </Pressable>
              </View>
            </View>
          )}
          ItemSeparatorComponent={() => <View style={{ height: 8 }} />}
          contentContainerStyle={{ padding: 16, paddingBottom: 24 }}
        />
      )}
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  container: { flex: 1 },
  bar: { flexDirection: 'row', gap: 8, padding: 12 },
  search: { flex: 1, height: 44, borderRadius: 8, borderWidth: StyleSheet.hairlineWidth, borderColor: '#E5E7EB', paddingHorizontal: 10, backgroundColor: 'white' },
  toggle: { paddingHorizontal: 10, borderRadius: 8, borderWidth: StyleSheet.hairlineWidth, borderColor: '#E5E7EB', alignItems: 'center', justifyContent: 'center' },
  toggleOn: { backgroundColor: '#111827', borderColor: '#111827' },
  toggleText: { fontWeight: '700', color: '#374151' },
  toggleTextOn: { color: 'white' },
  row: { padding: 12, borderRadius: 12, backgroundColor: '#F9FAFB', borderWidth: StyleSheet.hairlineWidth, borderColor: '#E5E7EB' },
  title: { fontWeight: '800', fontSize: 16 },
  meta: { color: '#6b7280' },
  badge: { paddingHorizontal: 8, paddingVertical: 2, borderRadius: 999, borderWidth: StyleSheet.hairlineWidth, borderColor: '#D1D5DB', backgroundColor: '#E5E7EB' },
  badgeText: { fontWeight: '800', fontSize: 10 },
  btn: { backgroundColor: '#111827', borderRadius: 10, paddingHorizontal: 12, paddingVertical: 8 },
  btnText: { color: 'white', fontWeight: '800' },
  error: { color: '#b91c1c', padding: 12 },
});

import { httpPost } from '@/api/http';
// @ts-ignore
import { Subscriptions } from '@/api/entities';
import { Stack } from 'expo-router';
import { useEffect, useState } from 'react';
import { Alert, Pressable, StyleSheet, Text, TextInput, View } from 'react-native';

export default function BillingScreen() {
  // Demo subtotal; replace with real cart subtotal
  const [subtotalCents] = useState(4999);
  const [code, setCode] = useState('');
  const [preview, setPreview] = useState<any>(null);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [summary, setSummary] = useState<any | null>(null);
  const [_loadingSummary, setLoadingSummary] = useState(false);
  const [showQtyEditor, setShowQtyEditor] = useState(false);
  const [qty, setQty] = useState<string>('3');

  useEffect(() => {
    const load = async () => {
      setLoadingSummary(true);
      try {
        const s = await Subscriptions.getSummary();
        setSummary(s);
        if (s?.quantity) setQty(String(s.quantity));
      } catch {
        // ignore
      } finally {
        setLoadingSummary(false);
      }
    };
    load();
  }, []);

  const onUpdateQuantity = async () => {
    const n = Number(qty);
    if (!Number.isFinite(n) || n < 3) {
      Alert.alert('Invalid quantity', 'Please enter 3 or higher.');
      return;
    }
    try {
      setBusy(true);
      await Subscriptions.updateQuantity(n);
      const s = await Subscriptions.getSummary();
      setSummary(s);
      setShowQtyEditor(false);
      Alert.alert('Updated', `Subscription updated to ${n} teams ($${(n * 2.5).toFixed(2)}/month).`);
    } catch (e: any) {
      Alert.alert('Update failed', e?.message || 'Unable to update quantity.');
    } finally {
      setBusy(false);
    }
  };

  async function onApply() {
    if (!code.trim()) return;
    setBusy(true); setError(null);
    try {
      const res = await httpPost('/promos/preview', { code, subtotal_cents: subtotalCents, service: 'membership' });
      if (!res?.valid) { setPreview(null); setError(res?.reason || 'invalid'); }
      else setPreview(res);
    } catch (e: any) {
      setPreview(null);
      setError(e?.message || 'Failed to apply promo');
    } finally { setBusy(false); }
  }

  async function onRedeem() {
    if (!code.trim()) return;
    setBusy(true);
    try {
      // For demo, fake an order id; replace with real checkout id
      const orderId = 'order_' + Math.random().toString(36).slice(2);
      const res = await httpPost('/promos/redeem', { code, subtotal_cents: subtotalCents, service: 'membership', order_id: orderId });
      if (!res?.ok) {
        Alert.alert('Promo', res?.error || 'Unable to redeem');
        return;
      }
      Alert.alert('Promo applied', `Discount: $${(res.discount_cents/100).toFixed(2)}\nNew total: $${(res.new_total_cents/100).toFixed(2)}`);
    } catch (e: any) {
      Alert.alert('Promo', e?.message || 'Unable to redeem');
    } finally { setBusy(false); }
  }
  return (
    <View style={styles.container}>
      <Stack.Screen options={{ title: 'Billing' }} />
      {/* Veteran Plan Banner */}
      {summary?.plan === 'veteran' && (
        <View style={styles.banner}>
          <Text style={styles.bannerTitle}>Veteran Plan</Text>
          <Text style={styles.bannerLine}>Paid teams: <Text style={styles.bold}>{summary.quantity ?? '—'}</Text></Text>
          <Text style={styles.bannerLine}>Monthly: <Text style={styles.bold}>${summary.monthly_cost?.toFixed?.(2) ?? ((summary.quantity || 0) * 2.5).toFixed(2)}</Text></Text>
          {!!summary.current_period_end && (
            <Text style={styles.bannerHint}>Renews: {new Date(summary.current_period_end).toLocaleDateString()}</Text>
          )}
          {!showQtyEditor ? (
            <Pressable style={styles.btnPrimary} onPress={() => setShowQtyEditor(true)}>
              <Text style={styles.btnPrimaryText}>Update Quantity</Text>
            </Pressable>
          ) : (
            <View style={styles.qtyRow}>
              <TextInput
                keyboardType="number-pad"
                value={qty}
                onChangeText={setQty}
                style={styles.qtyInput}
                placeholder="Teams"
              />
              <Pressable style={styles.btnPrimary} onPress={onUpdateQuantity} disabled={busy}>
                <Text style={styles.btnPrimaryText}>{busy ? '...' : 'Update'}</Text>
              </Pressable>
              <Pressable style={styles.btn} onPress={() => setShowQtyEditor(false)}>
                <Text style={styles.btnText}>Cancel</Text>
              </Pressable>
            </View>
          )}
        </View>
      )}
      <Text style={styles.title}>Billing</Text>
      <Text style={styles.subtitle}>Demo subtotal: ${ (subtotalCents/100).toFixed(2) }</Text>

      <View style={styles.applyRow}>
        <TextInput
          placeholder="Promo code"
          value={code}
          onChangeText={setCode}
          autoCapitalize="characters"
          style={styles.input}
        />
        <Pressable style={[styles.btn, busy ? styles.btnDisabled : null]} onPress={onApply} disabled={busy}>
          <Text style={styles.btnText}>{busy ? '...' : 'Apply'}</Text>
        </Pressable>
      </View>

      {error ? <Text style={styles.error}>Promo not valid: {error}</Text> : null}
      {preview?.valid ? (
        <View style={styles.previewBox}>
          <Text style={styles.previewLine}>Code: {preview.code}</Text>
          {preview.percent_off ? <Text style={styles.previewLine}>{preview.percent_off}% off</Text> : <Text style={styles.previewLine}>Complimentary</Text>}
          <Text style={styles.previewLine}>Discount: ${ (preview.discount_cents/100).toFixed(2) }</Text>
          <Text style={styles.previewLine}>New total: ${ (preview.new_total_cents/100).toFixed(2) }</Text>
          <Pressable style={styles.btnPrimary} onPress={onRedeem}>
            <Text style={styles.btnPrimaryText}>Redeem & Pay</Text>
          </Pressable>
        </View>
      ) : null}
    </View>
  );
}

