import { uploadFile } from '@/api/upload';
import { getApiBaseUrl } from '../../api/http';
import { useRef, useState } from 'react';
import { ActivityIndicator, Alert, Platform, Pressable, Text, View } from 'react-native';
import ViewShot, { captureRef } from 'react-native-view-shot';
import MatchBanner from './MatchBanner';

type Props = {
  leftImage?: string | null;
  rightImage?: string | null;
  leftName?: string;
  rightName?: string;
  bannerHeight?: number;
  onUploaded?: (url: string) => void;
  appearance?: 'classic' | 'sparkle' | 'sporty';
};

export default function MatchBannerCapture({ leftImage, rightImage, leftName, rightName, bannerHeight = 260, onUploaded, appearance = 'classic' }: Props) {
  const viewRef = useRef<View | null>(null);
  const [uploading, setUploading] = useState(false);

  const captureAndUpload = async () => {
    if (!viewRef.current) return;
    setUploading(true);
    try {
      // Capture banner as an image
      const uri = await captureRef(viewRef, { format: 'png', quality: 0.9 });

      // Upload image using centralized base URL
      const uploaded = await uploadFile(getApiBaseUrl(), uri, 'match-banner.png', 'image/png');
      const bannerUrl = uploaded?.url || uploaded?.path;
      if (onUploaded && bannerUrl) onUploaded(bannerUrl);
      Alert.alert('Banner saved', 'Match banner uploaded successfully.');
    } catch (e: any) {
      console.error('Banner capture/upload failed', e);
      Alert.alert('Error', 'Failed to capture or upload banner. Please try again.');
    } finally {
      setUploading(false);
    }
  };

  return (
    <View>
      <ViewShot ref={(r: any) => { viewRef.current = r; }} options={{ format: 'png', quality: 0.9 }}>
  <MatchBanner leftImage={leftImage} rightImage={rightImage} leftName={leftName} rightName={rightName} height={bannerHeight} appearance={appearance} />
      </ViewShot>

      <Pressable onPress={captureAndUpload} style={{ marginTop: 12, padding: 12, backgroundColor: '#2563EB', borderRadius: 8, alignItems: 'center' }} disabled={uploading}>
        {uploading ? <ActivityIndicator color="#fff" /> : <Text style={{ color: '#fff', fontWeight: '700' }}>Capture & Upload Banner</Text>}
      </Pressable>
    </View>
  );
}

import { useEffect, useRef, useState } from 'react';
import { View } from 'react-native';

import ANIM_SPARKLE from '../../assets/animations/sparkle.json';
import ANIM_SPARKLE_BETTER from '../../assets/animations/sparkle_better.json';

// Dynamic Lottie wrapper - attempts to load lottie-react-native at runtime.
export default function MatchBannerLottie({ style, onLoaded, tintColor, size = 80, preset = 'sparkle', disabled = false }: { style?: any; onLoaded?: (loaded: boolean) => void; tintColor?: string; size?: number; preset?: 'classic' | 'sparkle' | 'sporty'; disabled?: boolean }) {
  const [LottieView, setLottieView] = useState<any>(null)
  const animationRef = useRef<any>(null)
  const onLoadedRef = useRef<typeof onLoaded | undefined>(onLoaded);

  // keep latest onLoaded in a ref so the dynamic-import effect does not need it
  useEffect(() => { onLoadedRef.current = onLoaded; }, [onLoaded]);

  useEffect(() => {
    let mounted = true;

    if (disabled) {
      setLottieView(null);
      try { onLoadedRef.current && onLoadedRef.current(false); } catch {}
      return () => {
        mounted = false;
      };
    }

    (async () => {
      try {
        const mod = await import('lottie-react-native');
        if (mounted) {
          setLottieView(() => mod.default || mod);
          try { onLoadedRef.current && onLoadedRef.current(true); } catch {}
        }
      } catch {
        try { onLoadedRef.current && onLoadedRef.current(false); } catch {}
      }
    })();

    return () => {
      mounted = false;
    };
  }, [disabled]);

  if (disabled || !LottieView) {
    // show nothing (or a tiny loader) when lottie isn't available
    return null
  }

  // pick asset based on preset. Only reference animation files that actually exist in the repo
  // to avoid Metro bundler resolution errors. If you add new JSON assets, update this map.

  let anim: any = ANIM_SPARKLE_BETTER;
  if (preset === 'sparkle') {
    anim = ANIM_SPARKLE_BETTER;
  } else if (preset === 'sporty') {
    // sporty preset currently uses the generic sparkle placeholder until a dedicated asset is added
    anim = ANIM_SPARKLE;
  } else {
    // classic maps to the simple sparkle placeholder
    anim = ANIM_SPARKLE;
  }

  return (
    <View style={style} pointerEvents="none">
      <LottieView
        ref={animationRef}
        source={anim}
        autoPlay
        loop
        style={{ width: size, height: size }}
        colorFilters={tintColor ? [{ keypath: 'dot', color: tintColor }] : undefined}
      />
    </View>
  )
}

