interface Game {
  id: string;
  opponent: string; // Keep for backward compatibility
  homeTeam?: string;
  awayTeam?: string;
  date: string;
  time: string;
  location: string;
  type: 'home' | 'away' | 'neutral';
  status: 'upcoming' | 'completed' | 'cancelled' | 'pending';
  approval_status?: 'pending' | 'approved' | 'rejected';
  banner_url?: string; // Add banner URL support
  cover_image_url?: string; // Add cover image URL support
  score?: {
    team: number;
    opponent: number;
  };
}

interface SeasonStats {
  wins: number;
  losses: number;
  ties: number;
  gamesPlayed: number;
  totalGames: number;
  pointsFor: number;
  pointsAgainst: number;
}

interface StandingsTeam {
  id: string;
  name: string;
  wins: number;
  losses: number;
  ties: number;
  pointsFor: number;
  pointsAgainst: number;
  winPercentage: number;
  streak: string;
  lastGame: string;
}

interface PlayoffMatchup {
  id: string;
  round: number;
  position: number;
  team1?: StandingsTeam;
  team2?: StandingsTeam;
  winner?: StandingsTeam;
  score1?: number;
  score2?: number;
  status: 'upcoming' | 'completed' | 'in-progress';
  gameDate?: string;
}

