import { Organization } from '@/api/entities';
import { Colors } from '@/constants/Colors';
import { useCustomColorScheme } from '@/hooks/useCustomColorScheme';
import { Ionicons } from '@expo/vector-icons';
import { Stack, useLocalSearchParams, useRouter } from 'expo-router';
import { useCallback, useEffect, useState } from 'react';
import { ActivityIndicator, Alert, Modal, Pressable, RefreshControl, ScrollView, StyleSheet, Text, TextInput, View } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';

type JoinRequest = {
  id: string;
  organization_id: string;
  organization_name: string;
  team_id: string;
  team_name: string;
  message: string;
  requester_id: string;
  requester_name: string;
  status: 'pending' | 'approved' | 'rejected';
  created_at: string;
  approved_at?: string;
  rejected_at?: string;
  rejection_reason?: string;
};

export default function OrganizationJoinRequestsScreen() {
  const colorScheme = useCustomColorScheme();
  const theme = Colors[colorScheme];
  const router = useRouter();
  const params = useLocalSearchParams<{ organization_id: string; organization_name?: string }>();

  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [requests, setRequests] = useState<JoinRequest[]>([]);
  const [filter, setFilter] = useState<'pending' | 'all'>('pending');
  const [error, setError] = useState<string | null>(null);
  const [processingId, setProcessingId] = useState<string | null>(null);
  const [rejectModal, setRejectModal] = useState<{ visible: boolean; request: JoinRequest | null; reason: string }>({ visible: false, request: null, reason: '' });

  const loadRequests = useCallback(async () => {
    if (!params.organization_id) return;

    setLoading(true);
    setError(null);
    try {
      const status = filter === 'pending' ? 'pending' : undefined;
      const data = await Organization.getJoinRequests(params.organization_id, status);
      setRequests(Array.isArray(data) ? data : []);
    } catch (err: any) {
      console.error('[OrganizationJoinRequests] Error loading requests:', err);
      setError(err?.message || 'Failed to load join requests');
    } finally {
      setLoading(false);
    }
  }, [params.organization_id, filter]);

  const onRefresh = useCallback(async () => {
    setRefreshing(true);
    await loadRequests();
    setRefreshing(false);
  }, [loadRequests]);

  useEffect(() => {
    loadRequests();
  }, [loadRequests]);

  const handleApprove = async (request: JoinRequest) => {
    Alert.alert(
      'Approve Request',
      `Allow "${request.team_name}" to join ${params.organization_name || 'this organization'}?`,
      [
        { text: 'Cancel', style: 'cancel' },
        {
          text: 'Approve',
          style: 'default',
          onPress: async () => {
            setProcessingId(request.id);
            try {
              await Organization.approveJoinRequest(request.id);
              Alert.alert('Success', `${request.team_name} has been added to your organization!`);
              await loadRequests();
            } catch (err: any) {
              console.error('[OrganizationJoinRequests] Error approving request:', err);
              Alert.alert('Error', err?.message || 'Failed to approve request');
            } finally {
              setProcessingId(null);
            }
          },
        },
      ]
    );
  };

  const handleReject = (request: JoinRequest) => {
    setRejectModal({ visible: true, request, reason: '' });
  };

  const submitReject = async () => {
    if (!rejectModal.request) return;
    setProcessingId(rejectModal.request.id);
    try {
      await Organization.rejectJoinRequest(rejectModal.request.id, rejectModal.reason.trim() || undefined);
      Alert.alert('Request Rejected', `${rejectModal.request.team_name} has been notified.`);
      await loadRequests();
    } catch (err: any) {
      console.error('[OrganizationJoinRequests] Error rejecting request:', err);
      Alert.alert('Error', err?.message || 'Failed to reject request');
    } finally {
      setProcessingId(null);
      setRejectModal({ visible: false, request: null, reason: '' });
    }
  };

  const formatDate = (dateString: string): string => {
    try {
      const date = new Date(dateString);
      const now = new Date();
      const diffMs = now.getTime() - date.getTime();
      const diffMins = Math.floor(diffMs / 60000);
      const diffHours = Math.floor(diffMs / 3600000);
      const diffDays = Math.floor(diffMs / 86400000);

      if (diffMins < 1) return 'Just now';
      if (diffMins < 60) return `${diffMins}m ago`;
      if (diffHours < 24) return `${diffHours}h ago`;
      if (diffDays < 7) return `${diffDays}d ago`;

      return date.toLocaleDateString(undefined, { month: 'short', day: 'numeric' });
    } catch {
      return dateString;
    }
  };

  const pendingRequests = requests.filter((r) => r.status === 'pending');
  const processedRequests = requests.filter((r) => r.status !== 'pending');

  return (
    <SafeAreaView style={[styles.container, { backgroundColor: theme.background }]} edges={['top']}>
      <Stack.Screen
        options={{
          title: 'Team Join Requests',
          headerShown: false,
        }}
      />

      {/* Custom Header */}
      <View style={[styles.header, { backgroundColor: theme.background, borderColor: theme.border }]}>
        <Pressable onPress={() => void router.back()} style={styles.backButton}>
          <Ionicons name="arrow-back" size={24} color={theme.text} />
        </Pressable>
        <View style={styles.headerTextContainer}>
          <Text style={[styles.headerTitle, { color: theme.text }]}>Team Requests</Text>
          {params.organization_name && (
            <Text style={[styles.headerSubtitle, { color: theme.mutedText }]} numberOfLines={1}>
              {params.organization_name}
            </Text>
          )}
        </View>
        <View style={{ width: 40 }} />
      </View>

      {/* Filter Tabs */}
      <View style={[styles.filterContainer, { backgroundColor: theme.background, borderColor: theme.border }]}>
        <Pressable
          onPress={() => setFilter('pending')}
          style={[
            styles.filterButton,
            { backgroundColor: filter === 'pending' ? theme.tint : 'transparent' },
          ]}
        >
          <Text
            style={[
              styles.filterText,
              { color: filter === 'pending' ? '#fff' : theme.text },
            ]}
          >
            Pending {pendingRequests.length > 0 ? `(${pendingRequests.length})` : ''}
          </Text>
        </Pressable>
        <Pressable
          onPress={() => setFilter('all')}
          style={[
            styles.filterButton,
            { backgroundColor: filter === 'all' ? theme.tint : 'transparent' },
          ]}
        >
          <Text
            style={[
              styles.filterText,
              { color: filter === 'all' ? '#fff' : theme.text },
            ]}
          >
            All
          </Text>
        </Pressable>
      </View>

      {loading && !refreshing ? (
        <View style={styles.loadingContainer}>
          <ActivityIndicator size="large" color={theme.tint} />
        </View>
      ) : error ? (
        <View style={styles.errorContainer}>
          <Ionicons name="alert-circle-outline" size={48} color={theme.mutedText} />
          <Text style={[styles.errorText, { color: theme.text }]}>{error}</Text>
          <Pressable onPress={loadRequests} style={[styles.retryButton, { backgroundColor: theme.tint }]}>
            <Text style={styles.retryText}>Retry</Text>
          </Pressable>
        </View>
      ) : (
        <ScrollView
          contentContainerStyle={styles.content}
          refreshControl={
            <RefreshControl
              refreshing={refreshing}
              onRefresh={onRefresh}
              tintColor={theme.tint}
              colors={[theme.tint]}
            />
          }
          showsVerticalScrollIndicator={false}
        >
          {requests.length === 0 ? (
            <View style={styles.emptyContainer}>
              <Ionicons name="checkmark-circle-outline" size={64} color={theme.mutedText} />
              <Text style={[styles.emptyTitle, { color: theme.text }]}>
                {filter === 'pending' ? 'No Pending Requests' : 'No Requests Yet'}
              </Text>
              <Text style={[styles.emptySubtitle, { color: theme.mutedText }]}>
                {filter === 'pending'
                  ? 'All caught up! New requests will appear here.'
                  : 'Coaches can request to join your organization from their team page.'}
              </Text>
            </View>
          ) : (
            <View style={styles.requestsList}>
              {requests.map((request) => {
                const isPending = request.status === 'pending';
                const isProcessing = processingId === request.id;

                return (
                  <View
                    key={request.id}
                    style={[
                      styles.requestCard,
                      { backgroundColor: theme.card, borderColor: theme.border },
                    ]}
                  >
                    {/* Team Info */}
                    <View style={styles.requestHeader}>
                      <View style={styles.requestHeaderText}>
                        <Text style={[styles.teamName, { color: theme.text }]}>
                          {request.team_name}
                        </Text>
                        <Text style={[styles.requesterName, { color: theme.mutedText }]}>
                          by {request.requester_name}
                        </Text>
                      </View>
                      <View
                        style={[
                          styles.statusBadge,
                          {
                            backgroundColor:
                              request.status === 'approved'
                                ? '#10b981'
                                : request.status === 'rejected'
                                  ? '#ef4444'
                                  : '#f59e0b',
                          },
                        ]}
                      >
                        <Text style={styles.statusText}>
                          {request.status.charAt(0).toUpperCase() + request.status.slice(1)}
                        </Text>
                      </View>
                    </View>

                    {/* Message */}
                    {request.message && (
                      <View style={[styles.messageContainer, { backgroundColor: theme.surface }]}>
                        <Text style={[styles.messageText, { color: theme.text }]}>
                          "{request.message}"
                        </Text>
                      </View>
                    )}

                    {/* Rejection Reason */}
                    {request.status === 'rejected' && request.rejection_reason && (
                      <View style={[styles.rejectionContainer, { backgroundColor: '#fef2f2', borderColor: '#fee2e2' }]}>
                        <Ionicons name="close-circle" size={16} color="#dc2626" />
                        <Text style={[styles.rejectionText, { color: '#dc2626' }]}>
                          {request.rejection_reason}
                        </Text>
                      </View>
                    )}

                    {/* Timestamp */}
                    <Text style={[styles.timestamp, { color: theme.mutedText }]}>
                      {formatDate(request.created_at)}
                    </Text>

                    {/* Action Buttons (only for pending requests) */}
                    {isPending && (
                      <View style={styles.actionButtons}>
                        <Pressable
                          onPress={() => handleReject(request)}
                          disabled={isProcessing}
                          style={[styles.actionButton, styles.rejectButton, { borderColor: theme.border }]}
                        >
                          {isProcessing ? (
                            <ActivityIndicator size="small" color="#dc2626" />
                          ) : (
                            <>
                              <Ionicons name="close-circle-outline" size={20} color="#dc2626" />
                              <Text style={[styles.rejectButtonText, { color: '#dc2626' }]}>Reject</Text>
                            </>
                          )}
                        </Pressable>
                        <Pressable
                          onPress={() => handleApprove(request)}
                          disabled={isProcessing}
                          style={[styles.actionButton, styles.approveButton, { backgroundColor: theme.tint }]}
                        >
                          {isProcessing ? (
                            <ActivityIndicator size="small" color="#fff" />
                          ) : (
                            <>
                              <Ionicons name="checkmark-circle-outline" size={20} color="#fff" />
                              <Text style={styles.approveButtonText}>Approve</Text>
                            </>
                          )}
                        </Pressable>
                      </View>
                    )}
                  </View>
                );
              })}
            </View>
          )}
        </ScrollView>
      )}

      <Modal
        visible={rejectModal.visible}
        transparent
        animationType="fade"
        onRequestClose={() => setRejectModal({ visible: false, request: null, reason: '' })}
      >
        <Pressable
          style={styles.modalBackdrop}
          onPress={() => setRejectModal({ visible: false, request: null, reason: '' })}
        >
          <Pressable style={[styles.modalCard, { backgroundColor: theme.background }]} onPress={() => {}}>
            <Text style={[styles.modalTitle, { color: theme.text }]}>Reject Request</Text>
            <Text style={[styles.modalSubtitle, { color: theme.mutedText }]}>
              {rejectModal.request ? `Optional reason for rejecting ${rejectModal.request.team_name}.` : ''}
            </Text>
            <TextInput
              placeholder="Reason (optional)"
              placeholderTextColor={theme.mutedText}
              style={[styles.modalInput, { color: theme.text, borderColor: theme.border }]}
              value={rejectModal.reason}
              onChangeText={(text) => setRejectModal((prev) => ({ ...prev, reason: text }))}
              multiline
              numberOfLines={3}
            />
            <View style={styles.modalActions}>
              <Pressable
                style={[styles.modalButton, { borderColor: theme.border }]}
                onPress={() => setRejectModal({ visible: false, request: null, reason: '' })}
              >
                <Text style={[styles.modalButtonText, { color: theme.text }]}>Cancel</Text>
              </Pressable>
              <Pressable
                style={[styles.modalButton, styles.modalButtonDanger]}
                onPress={submitReject}
                disabled={processingId === rejectModal.request?.id}
              >
                <Text style={[styles.modalButtonText, { color: '#fff' }]}>
                  {processingId === rejectModal.request?.id ? 'Rejecting...' : 'Reject'}
                </Text>
              </Pressable>
            </View>
          </Pressable>
        </Pressable>
      </Modal>
    </SafeAreaView>
  );
}

