import { Ionicons } from '@expo/vector-icons';
import { Stack, useLocalSearchParams, useRouter } from 'expo-router';
import { useEffect, useState } from 'react';
import { ActivityIndicator, Linking, Platform, Pressable, StyleSheet, Text, View } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
// @ts-ignore
import { User } from '@/api/entities';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Colors } from '@/constants/Colors';
import { useAuth } from '@/context/AuthProvider';
import { useColorScheme } from '@/hooks/useColorScheme';

export default function VerifyEmailScreen() {
  const router = useRouter();
  const colorScheme = useColorScheme() ?? 'light';
  const params = useLocalSearchParams<{ devCode?: string }>();
  const { pendingVerificationEmail, checkAuth } = useAuth();
  const [code, setCode] = useState('');
  const [loading, setLoading] = useState(false);
  const [info, setInfo] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [devCode, setDevCode] = useState<string | null>(null);
  const [isVerified, setIsVerified] = useState(false);

  // Redirect if user is not pending verification
  useEffect(() => {
    if (!pendingVerificationEmail) {
      router.replace('/sign-in');
    }
  }, [pendingVerificationEmail, router]);

  // Load dev code from params if available
  useEffect(() => {
    if (params.devCode) {
      setDevCode(params.devCode);
      setCode(params.devCode);
      console.log('[verify-email] Dev code loaded from params:', params.devCode);
    }
  }, [params.devCode]);

  const openEmailApp = async () => {
    try {
      // Try to open native email app
      let url = '';
      if (Platform.OS === 'ios') {
        url = 'message://'; // iOS Mail app
      } else if (Platform.OS === 'android') {
        url = 'mailto:'; // Android email apps
      }

      const canOpen = await Linking.canOpenURL(url);
      if (canOpen) {
        await Linking.openURL(url);
      } else {
        // Fallback to generic email URL
        await Linking.openURL('mailto:');
      }
    } catch {
      console.error('Failed to open email app:', error);
      setInfo('Please check your email app manually');
    }
  };

  const onVerify = async () => {
    if (!code.trim()) return;
    setLoading(true); setError(null); setInfo(null);
    try {
      console.log('[verify-email] Attempting to verify with code:', code.trim());
      const result = await User.verifyEmail(code.trim());
      console.log('[verify-email] Verification result:', result);
      setInfo('✅ Email verified successfully!');
      setCode(''); // Clear the code input
      setIsVerified(true);

      // After successful verification, call checkAuth to populate user state
      // AuthProvider will detect onboarding_completed and route accordingly
      try {
        if (__DEV__) console.log('[verify-email] Calling checkAuth after verification...');
        await checkAuth();
        // checkAuth will update user state, and AuthProvider will auto-route

        // Auto-redirect after 2 seconds to give user time to see success message
        setTimeout(() => {
          if (__DEV__) console.log('[verify-email] Auto-redirecting after verification...');
          // Don't need to manually route - AuthProvider will handle it based on user state
        }, 2000);
      } catch (userError) {
        console.error('[verify-email] Failed to get user info after verification:', userError);
        // Still show success but user needs to retry
        setInfo('✅ Email verified! Please check your account.');
      }
    } catch (e: any) {
      console.error('[verify-email] Verification failed:', e);
      const errorMsg = e?.message || e?.data?.error || 'Verification failed';
      setError(errorMsg);
    } finally {
      setLoading(false);
    }
  };

  const onResend = async () => {
    setLoading(true); setError(null); setInfo(null);
    try {
      console.log('[verify-email] Requesting new verification code...');
      const res: any = await User.requestVerification();
      console.log('[verify-email] Resend response:', res);
      setInfo(res?.dev_verification_code ? `Code sent (dev: ${res.dev_verification_code})` : 'Code sent');
    } catch (e: any) {
      console.error('[verify-email] Resend failed:', e);
      const errorMsg = e?.message || e?.data?.error || 'Resend failed';
      setError(errorMsg);
    } finally {
      setLoading(false);
    }
  };

  const onContinue = async () => {
    console.log('[verify-email] User clicked Continue, proceeding immediately...');
    // No need to manually route - AuthProvider will detect user state and redirect
    router.replace('/(tabs)/feed' as any);
  };

  return (
    <SafeAreaView style={[styles.container, { backgroundColor: Colors[colorScheme].background }]} edges={['top', 'bottom']}>
      <Stack.Screen 
        options={{ 
          title: 'Verify Email',
          headerShown: false,
        }} 
      />

      {/* Back Button */}
      <Pressable 
        onPress={() => void router.back()} 
        style={styles.backButton}
        hitSlop={8}
      >
        <Ionicons name="arrow-back" size={24} color={Colors[colorScheme].text} />
      </Pressable>

      {/* Header Icon */}
      <View style={styles.iconContainer}>
        <Ionicons name="mail-outline" size={64} color={colorScheme === 'dark' ? '#60A5FA' : '#2563EB'} />
      </View>

      <Text style={[styles.title, { color: Colors[colorScheme].text }]}>Check Your Email</Text>
      <Text style={[styles.subtitle, { color: Colors[colorScheme].mutedText }]}>
        We sent a 6-digit verification code to your email address. 
        Enter the code below to complete your registration.
      </Text>

      {error ? <Text style={styles.error}>{error}</Text> : null}
      {info ? <Text style={styles.info}>{info}</Text> : null}

      {/* Dev Code Display */}
      {devCode ? (
        <View style={styles.devCodeContainer}>
          <Ionicons name="bug-outline" size={16} color="#059669" />
          <Text style={styles.devCodeText}>Dev Code: {devCode}</Text>
        </View>
      ) : null}

      <View style={styles.codeSection}>
        <Text style={[styles.label, { color: Colors[colorScheme].text }]}>Verification Code</Text>
        <Input 
          placeholder="123456" 
          value={code} 
          onChangeText={setCode} 
          keyboardType="number-pad" 
          maxLength={6}
          style={styles.codeInput}
        />
      </View>

      {isVerified ? (
        <Button onPress={onContinue} style={styles.verifyButton}>
          <Text style={{ color: '#fff', fontSize: 16, fontWeight: '600' }}>Continue to App</Text>
        </Button>
      ) : (
        <Button onPress={onVerify} disabled={loading || code.trim().length < 4} style={styles.verifyButton}>
          {loading ? <ActivityIndicator color="#fff" /> : 'Verify Email'}
        </Button>
      )}

      {!isVerified && (
        <View style={styles.footer}>
          <Text style={[styles.footerText, { color: Colors[colorScheme].mutedText }]}>Didn't receive the code?</Text>
          <Pressable onPress={onResend} disabled={loading}>
            <Text style={[styles.linkText, { color: Colors[colorScheme].tint }, loading && styles.linkTextDisabled]}>Resend Code</Text>
          </Pressable>
        </View>
      )}

      {!isVerified && (
        <Pressable style={styles.skipButton} onPress={() => void router.replace('/onboarding/step-1-role')}>
          <Text style={[styles.skipText, { color: Colors[colorScheme].mutedText }]}>Skip for now</Text>
        </Pressable>
      )}

      {isVerified && (
        <Text style={[styles.autoRedirectText, { color: Colors[colorScheme].mutedText }]}>
          Automatically continuing in a few seconds...
        </Text>
      )}
    </SafeAreaView>
  );
}

