import { User } from '@/api/entities';
import * as AppleAuthentication from 'expo-apple-authentication';
import { useCallback, useEffect, useState } from 'react';
import { Platform } from 'react-native';

type AppleAuthResult = Awaited<ReturnType<typeof User.loginViaApple>>;

export function useAppleAuth() {
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [available, setAvailable] = useState<boolean>(false);

  useEffect(() => {
    let mounted = true;
    AppleAuthentication.isAvailableAsync()
      .then(v => { if (mounted) setAvailable(Boolean(v)); })
      .catch(() => { if (mounted) setAvailable(false); });
    return () => { mounted = false; };
  }, []);

  const signInWithApple = useCallback(async (): Promise<AppleAuthResult> => {
    setError(null);
    setLoading(true);
    try {
      console.log('[Apple Auth] Starting Apple sign in...');
      console.log('[Apple Auth] Calling AppleAuthentication.signInAsync...');

      // Determine availability: if Apple Sign In isn't available (e.g., Simulator),
      // fall back to a mock credential to allow local dev flows.
      const isSimulator = Platform.OS === 'ios' && !available;

      let credential;
      if (isSimulator) {
        console.log('[Apple Auth] SIMULATOR MODE - using mock credential');
        // Create a mock credential for testing
        credential = {
          user: 'sim-test-user-' + Date.now(),
          authorizationCode: null,
          identityToken: null,
          email: null,
          fullName: null,
          state: null,
          realUserStatus: 1,
        };
      } else {
        const attemptNativeSignIn = async (scopes: any[]) => {
          return AppleAuthentication.signInAsync({ requestedScopes: scopes });
        };

        try {
          // First attempt with standard scopes
          credential = await attemptNativeSignIn([
            AppleAuthentication.AppleAuthenticationScope.FULL_NAME,
            AppleAuthentication.AppleAuthenticationScope.EMAIL,
          ]);
        } catch (appleErr: any) {
          // Log detailed error for diagnostics
          console.error('[Apple Auth] signInAsync error (scoped):', {
            code: appleErr?.code,
            domain: appleErr?.domain,
            message: appleErr?.message,
            nativeStack: appleErr?.nativeStack?
              (Array.isArray(appleErr.nativeStack) ? appleErr.nativeStack.slice(0, 5) : appleErr.nativeStack) : undefined,
          });

          const code = String(appleErr?.code || '').toLowerCase();
          const msg = String(appleErr?.message || '').toLowerCase();
          const isUnknown = code.includes('unknown') || msg.includes('unknown');
          const isCanceled = code.includes('canceled') || msg.includes('canceled') || msg.includes('cancelled');

          if (isCanceled) throw appleErr; // propagate cancel handling

          // Second attempt: retry with no scopes (sometimes fixes unknown auth errors)
          try {
            console.log('[Apple Auth] Retrying Apple sign in with no scopes...');
            credential = await attemptNativeSignIn([]);
          } catch (retryErr: any) {
            console.error('[Apple Auth] signInAsync retry error (no scopes):', {
              code: retryErr?.code,
              domain: retryErr?.domain,
              message: retryErr?.message,
            });
            throw retryErr; // bubble up for general handler
          }
        }
      }
      console.log('[Apple Auth] Got credential:', { user: credential.user, hasToken: !!credential.identityToken });

      // Prefer identityToken. In Simulator this can be null; fall back to authorizationCode
      // or a stable dev-only token derived from credential.user so local auth works.
      const fallbackToken = credential.authorizationCode || (credential.user ? `sim-${credential.user}` : null);
      const identityToken = credential.identityToken || fallbackToken;
      if (!identityToken) {
        throw new Error('Apple sign-in did not provide a token');
      }

      console.log('[Apple Auth] Sending token to backend...');
      // Send token to your backend (mock accepts any non-empty string in dev)
      // Retry logic for network issues and timeouts
      let res: any = null;
      let attempts = 0;
      const maxAttempts = 3;

      while (attempts < maxAttempts) {
        try {
          res = await User.loginViaApple(identityToken);
          console.log('[Apple Auth] Backend response:', { hasToken: !!res?.access_token, needsOnboarding: res?.needs_onboarding });
          break;
        } catch (networkErr: any) {
          attempts++;
          const isRetryable = 
            networkErr?.message?.includes('Network request failed') ||
            networkErr?.message?.includes('timeout') ||
            networkErr?.message?.includes('server did not respond') ||
            networkErr?.status === 408 ||
            networkErr?.status === 0;

          if (isRetryable && attempts < maxAttempts) {
            console.log(`[Apple Auth] Retryable error (${networkErr?.message}), retry ${attempts}/${maxAttempts}...`);
            await new Promise(resolve => setTimeout(resolve, 2000 * attempts));
          } else {
            console.error('[Apple Auth] Non-retryable error or max attempts reached');
            throw networkErr;
          }
        }
      }

      if (res?.access_token) {
        return res;
      } else {
        throw new Error('Invalid login response from server');
      }
    } catch (err: any) {
      console.error('[Apple Auth] Error:', err);
      const message = err?.message || 'Apple sign-in failed';
      // Dev-only fallback: if native Apple auth fails on device, use mock token path
      if (__DEV__ && Platform.OS === 'ios') {
        try {
          console.log('[Apple Auth] Dev fallback: attempting server login with sim token...');
          const devToken = `sim-device-${Date.now()}`;
          const res = await User.loginViaApple(devToken);
          if (res?.access_token) {
            console.log('[Apple Auth] Dev fallback succeeded');
            return res as any;
          }
        } catch (fallbackErr) {
          console.error('[Apple Auth] Dev fallback failed:', fallbackErr);
          // continue to normal error mapping below
        }
      }

      // Don't show error for user cancellation
      if (message.toLowerCase().includes('cancel')) {
        throw new Error('Apple sign-in cancelled');
      }

      // User-friendly timeout message
      if (message.includes('timeout') || message.includes('server did not respond')) {
        const friendlyMessage = 'Unable to connect to server. Please check your internet connection and try again.';
        setError(friendlyMessage);
        throw new Error(friendlyMessage);
      }

      // Map common Apple auth errors to clearer guidance
      const friendlyHints =
        '\nTips: Ensure you are signed into iCloud on this device, Two‑Factor Authentication is enabled for your Apple ID (Settings > [your name] > Password & Security), and you have a working network connection.';

      if (message.toLowerCase().includes('authorization') || message.toLowerCase().includes('unknown')) {
        const friendly = 'Apple authorization failed.' + friendlyHints;
        setError(friendly);
        throw new Error(friendly);
      }

      setError(message + (Platform.OS === 'ios' ? friendlyHints : ''));
      throw err;
    } finally {
      setLoading(false);
    }
  }, [available]);

  return {
    signInWithApple,
    loading,
    error,
    ready: available,
  };
}

import * as SecureStore from 'expo-secure-store';
import React, { createContext, useContext, useEffect, useRef, useState } from 'react';
import { useColorScheme as useSystemColorScheme } from 'react-native';
// @ts-ignore JS exports
import { User } from '@/api/entities';

type ColorScheme = 'light' | 'dark' | 'system';
type ActualColorScheme = 'light' | 'dark';

interface ThemeContextType {
  colorScheme: ActualColorScheme;
  themePreference: ColorScheme;
  setThemePreference: (theme: ColorScheme) => void;
}

const ThemeContext = createContext<ThemeContextType | undefined>(undefined);

const THEME_STORAGE_KEY = 'vh_theme_preference';

function storageKeyForUser(userId?: string | null) {
  if (!userId) return THEME_STORAGE_KEY + '_global';
  return `${THEME_STORAGE_KEY}_${userId}`;
}

export function ThemeProvider({ children }: { children: React.ReactNode }) {
  const systemColorScheme = useSystemColorScheme();
  const [themePreference, setThemePreferenceState] = useState<ColorScheme>('system');
  const [isLoaded, setIsLoaded] = useState(false);
  const currentStorageKey = useRef<string>(storageKeyForUser(null));

  // Load theme preference from storage on app start
  // Load theme preference from storage on app start or when user changes
  useEffect(() => {
    let mounted = true;
    const loadTheme = async () => {
      try {
        // Try to resolve current user to scope the theme key per-account when possible
        let me: any = null;
        try {
          me = await User.me();
        } catch (_) {
          me = null;
        }
        const key = storageKeyForUser(me?.id ?? me?.user_id ?? null);
        currentStorageKey.current = key;
        const savedTheme = await SecureStore.getItemAsync(key);
        if (mounted && savedTheme && ['light', 'dark', 'system'].includes(savedTheme)) {
          setThemePreferenceState(savedTheme as ColorScheme);
        }
      } catch (error) {
        console.warn('Failed to load theme preference:', error);
      } finally {
        if (mounted) setIsLoaded(true);
      }
    };
    loadTheme();
    return () => { mounted = false; };
  }, []);

  // Calculate actual color scheme based on preference
  const colorScheme: ActualColorScheme = 
    themePreference === 'system' 
      ? (systemColorScheme ?? 'light') 
      : themePreference;

  // Save theme preference to storage when changed
  const setThemePreference = async (theme: ColorScheme) => {
    try {
      // Save to the scoped key (per-user when possible)
      const key = currentStorageKey.current || storageKeyForUser(null);
      await SecureStore.setItemAsync(key, theme);
      setThemePreferenceState(theme);
    } catch (error) {
      console.warn('Failed to save theme preference:', error);
      // Still update state even if storage fails
      setThemePreferenceState(theme);
    }
  };

  return (
    <ThemeContext.Provider value={{ colorScheme, themePreference, setThemePreference }}>
      {children}
    </ThemeContext.Provider>
  );
}

export function useCustomColorScheme(): ActualColorScheme {
  const context = useContext(ThemeContext);
  if (context === undefined) {
    // Fallback if used outside provider
    const systemColorScheme = useSystemColorScheme();
    return systemColorScheme ?? 'light';
  }
  return context.colorScheme;
}

export function useThemePreference() {
  const context = useContext(ThemeContext);
  if (context === undefined) {
    // Return default values if used outside provider instead of throwing
    console.warn('useThemePreference used outside ThemeProvider, returning defaults');
    return {
      themePreference: 'system' as ColorScheme,
      setThemePreference: () => {},
    };
  }
  return {
    themePreference: context.themePreference,
    setThemePreference: context.setThemePreference,
  };
}

import * as Location from 'expo-location';
import { useEffect, useState } from 'react';
import { Linking, Platform } from 'react-native';

export interface DeviceLocation {
  latitude: number;
  longitude: number;
  accuracy?: number;
  timestamp?: number;
}

export interface UseDeviceLocationResult {
  location: DeviceLocation | null;
  loading: boolean;
  error: string | null;
  permissionGranted: boolean | null;
  accuracyMeters: number | null;
  isPrecise: boolean;
  needsPreciseAccuracy: boolean;
  requestPermission: () => Promise<boolean>;
  openSettings: () => Promise<void>;
  refresh: () => Promise<void>;
}

/**
 * Hook to manage device location with permission handling and caching.
 * Caches the location for 10 minutes to avoid excessive GPS requests.
 * Handles permission denial gracefully.
 */
export function useDeviceLocation(): UseDeviceLocationResult {
  const [location, setLocation] = useState<DeviceLocation | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [permissionGranted, setPermissionGranted] = useState<boolean | null>(null);
  const [lastFetchTime, setLastFetchTime] = useState(0);
  const [accuracyMeters, setAccuracyMeters] = useState<number | null>(null);

  const CACHE_DURATION_MS = 10 * 60 * 1000; // 10 minutes
  const PRECISION_THRESHOLD = 200; // meters; >200 == approximate on Android

  const requestPermission = async (): Promise<boolean> => {
    try {
      const { status } = await Location.requestForegroundPermissionsAsync();
      const granted = status === 'granted';
      setPermissionGranted(granted);

      if (!granted) {
        setError('Location permission denied');
        setLoading(false);
        setAccuracyMeters(null);
        return false;
      }

      setError(null);
      setAccuracyMeters(null);
      await fetchLocation();
      return true;
    } catch (e: any) {
      const errMsg = e?.message || 'Failed to request location permission';
      setError(errMsg);
      setPermissionGranted(false);
      setLoading(false);
      setAccuracyMeters(null);
      return false;
    }
  };

  const assignLocation = (coords: Location.LocationObjectCoords, timestamp?: number) => {
    const loc: DeviceLocation = {
      latitude: coords.latitude,
      longitude: coords.longitude,
      accuracy: coords.accuracy ?? undefined,
      timestamp,
    };
    setLocation(loc);
    setAccuracyMeters(typeof coords.accuracy === 'number' ? coords.accuracy : null);
  };

  const fetchLocation = async () => {
    try {
      setLoading(true);
      setError(null);

      // Check cache first
      const now = Date.now();
      if (location && now - lastFetchTime < CACHE_DURATION_MS) {
        if (__DEV__) console.log('[location] Using cached location');
        setLoading(false);
        return;
      }

      // Try last known position first (faster, may be stale)
      const lastKnown = await Location.getLastKnownPositionAsync();
      if (lastKnown?.coords && (now - (lastKnown.timestamp || 0)) < 30 * 60 * 1000) {
        // Last known is less than 30 minutes old
        if (__DEV__) console.log('[location] Using last known position');
        assignLocation(lastKnown.coords, lastKnown.timestamp);
        setLastFetchTime(now);
        setLoading(false);
        return;
      }

      // Get fresh position with balanced accuracy
      if (__DEV__) console.log('[location] Fetching fresh location...');
      const fresh = await Location.getCurrentPositionAsync({
        accuracy: Location.Accuracy.Balanced,
      });

      if (fresh?.coords) {
        assignLocation(fresh.coords, fresh.timestamp);
        setLastFetchTime(now);
        setError(null);
      }
    } catch (e: any) {
      const errMsg = e?.message || 'Failed to fetch location';
      console.warn('[location] Fetch failed:', errMsg);
      setError(errMsg);
    } finally {
      setLoading(false);
    }
  };

  // Check permissions on mount
  useEffect(() => {
    (async () => {
      try {
        const { status } = await Location.getForegroundPermissionsAsync();
        const granted = status === 'granted';
        setPermissionGranted(granted);

        if (granted) {
          setAccuracyMeters(null);
          await fetchLocation();
        } else {
          setLoading(false);
        }
      } catch (e) {
        setError('Failed to check location permissions');
        setLoading(false);
      }
    })();
  }, []);

  const openSettings = async () => {
    if (typeof Linking.openSettings !== 'function') return;
    try {
      await Linking.openSettings();
    } catch (err) {
      if (__DEV__) console.warn('[location] Unable to open settings', err);
    }
  };

  const refresh = async () => {
    setLastFetchTime(0); // Clear cache
    await fetchLocation();
  };

  const isPrecise = accuracyMeters == null ? true : accuracyMeters <= PRECISION_THRESHOLD;
  const needsPreciseAccuracy = Platform.OS === 'android' && permissionGranted === true && !isPrecise;

  return {
    location,
    loading,
    error,
    permissionGranted,
    accuracyMeters,
    isPrecise,
    needsPreciseAccuracy,
    requestPermission,
    openSettings,
    refresh,
  };
}

export default useDeviceLocation;

import { User } from '@/api/entities';
import * as Application from 'expo-application';
import * as AuthSession from 'expo-auth-session';
import * as Google from 'expo-auth-session/providers/google';
import Constants from 'expo-constants';
import * as WebBrowser from 'expo-web-browser';
import { useCallback, useEffect, useMemo, useState } from 'react';
import { Platform } from 'react-native';

WebBrowser.maybeCompleteAuthSession();
const { makeRedirectUri } = AuthSession;

let sessionUrlProvider: {
  getRedirectUrl: (options?: Record<string, any>) => string;
  getStartUrl?: (authUrl: string, returnUrl: string, projectNameForProxy?: string) => string;
} | null = null;

try {
  // eslint-disable-next-line @typescript-eslint/no-var-requires
  sessionUrlProvider = require('expo-auth-session/build/SessionUrlProvider').default;
} catch {
  sessionUrlProvider = null;
}

type GoogleAuthResult = Awaited<ReturnType<typeof User.loginViaGoogle>>;

const googleClientConfig = (opts: { shouldUseProxy: boolean }) => {
  const androidClientId = process.env.EXPO_PUBLIC_GOOGLE_ANDROID_CLIENT_ID || undefined;
  const iosClientId = process.env.EXPO_PUBLIC_GOOGLE_IOS_CLIENT_ID || undefined;
  const webClientId = process.env.EXPO_PUBLIC_GOOGLE_WEB_CLIENT_ID || undefined;
  const expoClientId = process.env.EXPO_PUBLIC_GOOGLE_EXPO_CLIENT_ID || undefined;

    const isDevSimulator = opts.shouldUseProxy && Constants.appOwnership === 'expo' && Platform.OS === 'ios';

  if (isDevSimulator && webClientId) {
    return {
      androidClientId: webClientId,
      iosClientId: webClientId,
      webClientId,
      expoClientId: webClientId,
      forceWebClient: true,
    } as const;
  }

  return { androidClientId, iosClientId, webClientId, expoClientId, forceWebClient: false } as const;
};

const FORCE_PROXY_FLAG = process.env.EXPO_PUBLIC_GOOGLE_FORCE_PROXY === '1';
const FALLBACK_PROJECT_FULL_NAME = '@lime_prod/VarsityHubMobile';
const expoConfig: any = Constants.expoConfig ?? {};
const expoSlug: string | undefined = expoConfig.slug || expoConfig.name;
const expoOwner: string | undefined = expoConfig.owner;
const expoOriginalFullName: string | undefined = (expoConfig as any)?.extra?.expoGo?.projectFullName;
const derivedProjectFullName =
  typeof expoOriginalFullName === 'string'
    ? expoOriginalFullName
    : typeof expoSlug === 'string'
      ? `${expoOwner ? `@${expoOwner}` : '@anonymous'}/${expoSlug}`
      : undefined;
const PROJECT_FULL_NAME =
  process.env.EXPO_PUBLIC_EXPO_PROJECT_FULL_NAME || derivedProjectFullName || FALLBACK_PROJECT_FULL_NAME;

if (PROJECT_FULL_NAME && sessionUrlProvider?.getRedirectUrl) {
  const originalGetRedirectUrl = sessionUrlProvider.getRedirectUrl.bind(sessionUrlProvider);
  sessionUrlProvider.getRedirectUrl = (options?: Record<string, any>) =>
    originalGetRedirectUrl({ projectNameForProxy: PROJECT_FULL_NAME, ...(options || {}) });
  if (sessionUrlProvider.getStartUrl) {
    const originalGetStartUrl = sessionUrlProvider.getStartUrl.bind(sessionUrlProvider);
    sessionUrlProvider.getStartUrl = (authUrl: string, returnUrl: string, projectNameForProxy?: string) =>
      originalGetStartUrl(authUrl, returnUrl, projectNameForProxy ?? PROJECT_FULL_NAME);
  }
}

export function useGoogleAuth() {
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const proxyRequested = FORCE_PROXY_FLAG || Constants.appOwnership === null;
  const shouldUseProxy = proxyRequested && !!PROJECT_FULL_NAME;

  const clients = useMemo(() => googleClientConfig({ shouldUseProxy }), [shouldUseProxy]);
  const isConfigured = useMemo(
    () => Boolean(clients.androidClientId || clients.iosClientId || clients.webClientId || clients.expoClientId),
    [clients],
  );

  const redirectUri = useMemo(() => {
    try {
      if (shouldUseProxy && PROJECT_FULL_NAME) {
        return AuthSession.getRedirectUrl();
      }
    } catch (err) {
      console.warn('[google-auth] failed to build proxy redirect uri', err);
    }
    return makeRedirectUri({
      native: `${Application.applicationId}:/oauthredirect`,
      scheme: process.env.EXPO_PUBLIC_APP_SCHEME || 'varsityhubmobile',
    });
  }, [shouldUseProxy]);

  const redirectOptions = useMemo(() => {
    // Use default redirect behavior
    return {} as const;
  }, [shouldUseProxy]);

  useEffect(() => {
    console.log('[google-auth]', {
      redirectUri,
      shouldUseProxy,
      projectNameForProxy: shouldUseProxy ? PROJECT_FULL_NAME : null,
      appOwnership: Constants.appOwnership,
      executionEnvironment: Constants.executionEnvironment,
    });
    if (proxyRequested && !PROJECT_FULL_NAME) {
      console.warn(
        '[google-auth] Proxy requested but project full name could not be resolved. Falling back to custom scheme.',
      );
    }
  }, [redirectUri, shouldUseProxy, proxyRequested]);

  // Create request config - use placeholder values if not configured
  // The hook must be called unconditionally (React rules of hooks)
  const requestConfig: Google.GoogleAuthRequestConfig = useMemo(() => {
    // If configured, use real values
    if (isConfigured) {
      return {
        scopes: ['profile', 'email'],
        redirectUri,
        androidClientId: clients.androidClientId || undefined,
        iosClientId: clients.iosClientId || undefined,
        webClientId: clients.webClientId || undefined,
        clientId: clients.expoClientId || undefined,
      };
    }

    // If not configured, provide placeholder values that satisfy the hook
    // We won't actually use this to sign in (isConfigured check prevents it)
    return {
      scopes: ['profile', 'email'],
      redirectUri,
      // Use fake but valid-looking client IDs for all platforms
      androidClientId: '000000000000-xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx.apps.googleusercontent.com',
      iosClientId: '000000000000-yyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyy.apps.googleusercontent.com',
      webClientId: '000000000000-zzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzz.apps.googleusercontent.com',
      clientId: '000000000000-wwwwwwwwwwwwwwwwwwwwwwwwwwwwwwww.apps.googleusercontent.com',
    };
  }, [isConfigured, clients, redirectUri]);

  // Always call useAuthRequest (React rules of hooks)
  const [request, , promptAsync] = Google.useAuthRequest(requestConfig, redirectOptions);

  const signInWithGoogle = useCallback(async (): Promise<GoogleAuthResult> => {
    if (!isConfigured) {
      throw new Error('Google sign-in is not configured');
    }
    if (!request) {
      throw new Error('Google sign-in is not ready yet');
    }
    setError(null);
    setLoading(true);
    try {
      const response = await promptAsync();
      if (response.type !== 'success' || !response.authentication?.idToken) {
        throw new Error(response.type === 'dismiss' ? 'Google sign-in cancelled' : 'Google sign-in failed');
      }
      const serverResponse = await User.loginViaGoogle(response.authentication.idToken);
      return serverResponse as GoogleAuthResult;
    } catch (err: any) {
      const message = err?.message || 'Unable to sign in with Google';
      setError(message);
      throw err instanceof Error ? err : new Error(message);
    } finally {
      setLoading(false);
    }
  }, [isConfigured, promptAsync, request]);

  return {
    ready: isConfigured && !!request,
    loading,
    error,
    signInWithGoogle,
  };
}

import { User } from '@/api/entities';
import { useCallback, useRef, useState } from 'react';
import type { PostsCounts } from './useProfilePosts';

export type InteractionType = 'all' | 'like' | 'comment' | 'repost' | 'save';
export type InteractionSort = 'newest' | 'most_upvoted' | 'most_commented';

export interface UseProfileInteractionsResult {
  interactions: any[];
  loading: boolean;
  hasMore: boolean;
  cursor: string | null;
  counts: PostsCounts | null;
  type: InteractionType;
  setType: (type: InteractionType) => void;
  refresh: (userId: string) => Promise<void>;
  loadMore: (userId: string) => Promise<void>;
}

/**
 * Hook for managing user's interactions (likes, comments, etc.) with pagination
 * Includes filtering by interaction type and request-in-flight guards
 */
export function useProfileInteractions(
  sort: InteractionSort = 'newest',
  initialType: InteractionType = 'all'
): UseProfileInteractionsResult {
  const [interactions, setInteractions] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [cursor, setCursor] = useState<string | null>(null);
  const [hasMore, setHasMore] = useState(true);
  const [counts, setCounts] = useState<PostsCounts | null>(null);
  const [type, setType] = useState<InteractionType>(initialType);
  const requestInFlight = useRef(false);

  const refresh = useCallback(async (userId: string) => {
    // Prevent concurrent requests
    if (requestInFlight.current) {
      console.log('[useProfileInteractions] Request already in flight, skipping');
      return;
    }

    requestInFlight.current = true;
    setLoading(true);

    try {
      const page = await User.interactionsForProfile(String(userId), {
        limit: 10,
        type,
        sort,
      });

      setInteractions(page.items || []);
      setCursor(page.nextCursor || null);
      setHasMore(Boolean(page.nextCursor));

      if (page.counts) {
        setCounts(page.counts);
      }
    } catch (error: any) {
      console.error('[useProfileInteractions] Failed to refresh interactions:', error);
      // Don't throw - let parent handle via error state
    } finally {
      requestInFlight.current = false;
      setLoading(false);
    }
  }, [type, sort]);

  const loadMore = useCallback(async (userId: string) => {
    if (loading || !hasMore || requestInFlight.current) {
      return;
    }

    requestInFlight.current = true;
    setLoading(true);

    try {
      const page = await User.interactionsForProfile(String(userId), {
        limit: 10,
        type,
        sort,
        cursor: cursor || undefined,
      });

      setInteractions((prev) => [...prev, ...(page.items || [])]);
      setCursor(page.nextCursor || null);
      setHasMore(Boolean(page.nextCursor));

      if (page.counts) {
        setCounts(page.counts);
      }
    } catch (error: any) {
      console.error('[useProfileInteractions] Failed to load more interactions:', error);
    } finally {
      requestInFlight.current = false;
      setLoading(false);
    }
  }, [cursor, hasMore, loading, type, sort]);

  return {
    interactions,
    loading,
    hasMore,
    cursor,
    counts,
    type,
    setType,
    refresh,
    loadMore,
  };
}

import { Organization, Team } from '@/api/entities';
import { useEffect, useState } from 'react';

export interface UseProfileOrganizationsResult {
  organizations: any[];
  loading: boolean;
}

/**
 * Hook for loading user's organizations asynchronously
 * Fetches user's teams and hydrates their organizations in the background
 * Doesn't block profile rendering
 */
export function useProfileOrganizations(userId: string | null | undefined): UseProfileOrganizationsResult {
  const [organizations, setOrganizations] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    if (!userId) {
      setOrganizations([]);
      return;
    }

    let cancelled = false;

    const loadOrganizations = async () => {
      setLoading(true);

      try {
        // Fetch user's teams
        const myTeams = await Team.list('', true); // mine=true

        if (cancelled || !Array.isArray(myTeams) || myTeams.length === 0) {
          setLoading(false);
          return;
        }

        // Extract unique organization IDs from teams
        const orgIds = new Set<string>();
        const orgNames = new Set<string>();

        myTeams.forEach((team: any) => {
          if (team.organization_id) {
            orgIds.add(team.organization_id);
          }
          // Also extract organization from team name (e.g., "SHS Men's Soccer" -> "SHS")
          if (team.name) {
            const nameParts = String(team.name).split(/\s+/);
            if (nameParts.length > 0) {
              orgNames.add(nameParts[0]);
            }
          }
        });

        // Try to fetch by ID first
        if (orgIds.size > 0) {
          const orgPromises = Array.from(orgIds).map(id =>
            Organization.get(id).catch(() => null)
          );

          const orgsData = await Promise.all(orgPromises);
          const validOrgs = orgsData.filter(org => org !== null);

          if (!cancelled && validOrgs.length > 0) {
            setOrganizations(validOrgs);
            setLoading(false);
            return;
          }
        }

        // If no orgs found by ID, try searching by name
        if (!cancelled && orgIds.size === 0 && orgNames.size > 0) {
          const searchPromises = Array.from(orgNames).map(name =>
            Organization.list(name, 5).catch(() => [])
          );

          const searchResults = await Promise.all(searchPromises);
          const flatResults = searchResults.flat();

          // Deduplicate by ID
          const uniqueOrgs = flatResults.filter((org: any, index: number, self: any[]) =>
            org && org.id && self.findIndex((o: any) => o?.id === org.id) === index
          );

          if (!cancelled) {
            setOrganizations(uniqueOrgs);
          }
        }
      } catch (error) {
        console.error('[useProfileOrganizations] Failed to load organizations:', error);
        // Don't throw - just log and leave organizations empty
      } finally {
        if (!cancelled) {
          setLoading(false);
        }
      }
    };

    loadOrganizations();

    return () => {
      cancelled = true;
    };
  }, [userId]);

  return {
    organizations,
    loading,
  };
}

import { User } from '@/api/entities';
import { useCallback, useRef, useState } from 'react';

export interface PostsCounts {
  posts: number;
  likes: number;
  comments: number;
  reposts: number;
  saves: number;
}

export interface UseProfilePostsResult {
  posts: any[];
  loading: boolean;
  hasMore: boolean;
  cursor: string | null;
  counts: PostsCounts | null;
  refresh: (userId: string) => Promise<void>;
  loadMore: (userId: string) => Promise<void>;
  setPosts: React.Dispatch<React.SetStateAction<any[]>>;
}

/**
 * Hook for managing user's posts with pagination
 * Includes request-in-flight guards to prevent duplicate fetches
 */
export function useProfilePosts(sort: 'newest' | 'most_upvoted' | 'most_commented' = 'newest'): UseProfilePostsResult {
  const [posts, setPosts] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [cursor, setCursor] = useState<string | null>(null);
  const [hasMore, setHasMore] = useState(true);
  const [counts, setCounts] = useState<PostsCounts | null>(null);
  const requestInFlight = useRef(false);

  const refresh = useCallback(async (userId: string) => {
    // Prevent concurrent requests
    if (requestInFlight.current) {
      console.log('[useProfilePosts] Request already in flight, skipping');
      return;
    }

    requestInFlight.current = true;
    setLoading(true);

    try {
      const page = await User.postsForProfile(String(userId), { limit: 10, sort });

      setPosts(page.items || []);
      setCursor(page.nextCursor || null);
      setHasMore(Boolean(page.nextCursor));

      if (page.counts) {
        setCounts(page.counts);
      }
    } catch (error: any) {
      console.error('[useProfilePosts] Failed to refresh posts:', error);
      // Don't throw - let parent handle via error state
    } finally {
      requestInFlight.current = false;
      setLoading(false);
    }
  }, [sort]);

  const loadMore = useCallback(async (userId: string) => {
    if (loading || !hasMore || requestInFlight.current) {
      return;
    }

    requestInFlight.current = true;
    setLoading(true);

    try {
      const page = await User.postsForProfile(String(userId), {
        limit: 10,
        sort,
        cursor: cursor || undefined,
      });

      setPosts((prev) => [...prev, ...(page.items || [])]);
      setCursor(page.nextCursor || null);
      setHasMore(Boolean(page.nextCursor));

      if (page.counts) {
        setCounts(page.counts);
      }
    } catch (error: any) {
      console.error('[useProfilePosts] Failed to load more posts:', error);
    } finally {
      requestInFlight.current = false;
      setLoading(false);
    }
  }, [cursor, hasMore, loading, sort]);

  return {
    posts,
    loading,
    hasMore,
    cursor,
    counts,
    refresh,
    loadMore,
    setPosts,
  };
}

import { useCallback, useMemo } from 'react';
import { Alert, Share } from 'react-native';
import * as Clipboard from 'expo-clipboard';
import AppLinks, { ShareableLink } from '@/utils/links';

export type ShareLinkKind = 'post' | 'highlight' | 'event' | 'game' | 'team' | 'user';

interface ShareLinkOptions {
  kind: ShareLinkKind;
  id?: string | number | null;
  title?: string | null;
  caption?: string | null;
  contextLines?: Array<string | null | undefined>;
}

const formatLink = (options: ShareLinkOptions): ShareableLink | null => {
  if (options.id == null) return null;
  const id = String(options.id);
  switch (options.kind) {
    case 'post':
      return AppLinks.post(id, options.caption || undefined);
    case 'highlight':
      return AppLinks.highlight(id, options.caption || undefined);
    case 'game':
      return AppLinks.game(id, options.title || undefined);
    case 'event':
      return AppLinks.event(id, options.title || undefined);
    case 'team':
      return AppLinks.team(id, options.title || undefined);
    case 'user':
      return AppLinks.user(id, options.title || undefined);
    default:
      return null;
  }
};

export function useShareLink(options: ShareLinkOptions) {
  const link = useMemo(() => formatLink(options), [
    options.caption,
    options.id,
    options.kind,
    options.title,
  ]);

  const contextMessage = useMemo(() => {
    if (!link) return '';
    const lines = (options.contextLines || []).filter(Boolean) as string[];
    if (!lines.length) return link.shareMessage;
    return `${lines.join('\n')}\n${link.shareMessage}`;
  }, [link, options.contextLines]);

  const copyLink = useCallback(
    async (silent = false) => {
      if (!link) {
        if (!silent) Alert.alert('Share unavailable', 'Link is still loading.');
        return;
      }
      try {
        await Clipboard.setStringAsync(link.webUrl);
        if (!silent) Alert.alert('Link copied', 'You can paste it anywhere to share.');
      } catch (error) {
        console.error('[share] Failed to copy link', error);
        if (!silent) Alert.alert('Copy failed', 'Unable to copy the link right now.');
      }
    },
    [link],
  );

  const share = useCallback(async () => {
    if (!link) {
      Alert.alert('Share unavailable', 'Link is still loading.');
      return;
    }
    try {
      await Share.share({
        message: contextMessage || link.shareMessage,
        url: link.webUrl,
        title: options.title || link.webUrl,
      });
    } catch (error) {
      console.warn('[share] Failed to open share sheet', error);
      await copyLink(true);
      Alert.alert('Share unavailable', 'Link copied to clipboard so you can paste it manually.');
    }
  }, [contextMessage, copyLink, link, options.title]);

  return {
    share,
    copyLink,
    shareMessage: contextMessage || link?.shareMessage || '',
    webUrl: link?.webUrl ?? null,
    isReady: !!link,
  };
}

export default useShareLink;
